INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5969688, 874261, 117035, '<td valign="top">I enjoyed the perspectives in this shot. Clean, clear reflection.</td>', 'I enjoyed the perspectives in this shot. Clean, clear reflection.', '2010-04-26 01:06:33.000000', NULL, 1),
(5969697, 874241, 117035, '<td valign="top">Nice lines. The trees however would have been better coming from equal angels. Still great horizon line and nice contrasts.</td>', 'Nice lines. The trees however would have been better coming from equal angels. Still great horizon line and nice contrasts.', '2010-04-26 01:08:26.000000', NULL, 1),
(5969708, 873411, 117035, '<td valign="top">Great subject. I like the contrast between the verticals and horizon line. The shadows and sun''s flare are a great contrast too.</td>', 'Great subject. I like the contrast between the verticals and horizon line. The shadows and sun''s flare are a great contrast too.', '2010-04-26 01:09:58.000000', NULL, 1),
(5969718, 874218, 117035, '<td valign="top">Nice subjects. Lovely clear difference between the trees and the sky.</td>', 'Nice subjects. Lovely clear difference between the trees and the sky.', '2010-04-26 01:10:52.000000', NULL, 1),
(5969722, 873712, 117035, '<td valign="top">Lovely image.</td>', 'Lovely image.', '2010-04-26 01:11:20.000000', NULL, 1),
(5969731, 873478, 117035, '<td valign="top">Great geographical lines. Wonderful subject. This almost looks like a painting showing brush strokes. Well done. Lovely.</td>', 'Great geographical lines. Wonderful subject. This almost looks like a painting showing brush strokes. Well done. Lovely.', '2010-04-26 01:12:16.000000', NULL, 1),
(5969737, 874056, 117035, '<td valign="top">Beautiful imagery here. I love the mood and the title expresses this so very well. I''m intrigued by the evenness of the tones, as it adds to the serenity of the overall picture. Nice.</td>', 'Beautiful imagery here. I love the mood and the title expresses this so very well. I''m intrigued by the evenness of the tones, as it adds to the serenity of the overall picture. Nice.', '2010-04-26 01:13:21.000000', NULL, 1),
(5969748, 873942, 117035, '<td valign="top">Really draws you into the image. Wonderful.</td>', 'Really draws you into the image. Wonderful.', '2010-04-26 01:14:36.000000', NULL, 1),
(5969751, 873332, 117035, '<td valign="top">Lovely texture and mood. Almost surreal and magical.</td>', 'Lovely texture and mood. Almost surreal and magical.', '2010-04-26 01:14:57.000000', NULL, 1),
(5969760, 873054, 114285, '<td valign="top">Cool pic, looks like where i live, are you from Perth ??</td>', 'Cool pic, looks like where i live, are you from Perth ??', '2010-04-26 01:16:17.000000', NULL, 1),
(5969761, 873824, 117035, '<td valign="top">Lovely work. Serene and thought provoking.</td>', 'Lovely work. Serene and thought provoking.', '2010-04-26 01:16:25.000000', NULL, 1),
(5969782, 873822, 117035, '<td valign="top">Great image. Very striking.</td>', 'Great image. Very striking.', '2010-04-26 01:18:25.000000', NULL, 1),
(5969787, 872817, 114285, '<td valign="top">Love this one.</td>', 'Love this one.', '2010-04-26 01:19:06.000000', NULL, 1),
(5969796, 873012, 117035, '<td valign="top">Lovely composition. The winding lines draw the eye to the island. Nice tones.</td>', 'Lovely composition. The winding lines draw the eye to the island. Nice tones.', '2010-04-26 01:19:59.000000', NULL, 1),
(5969799, 874165, 117035, '<td valign="top">Wonderful subject. A contrast of two worlds.</td>', 'Wonderful subject. A contrast of two worlds.', '2010-04-26 01:20:26.000000', NULL, 1),
(5969808, 873648, 72670, '<td valign="top">Sara, so glad that you decided to enter this one. I love it!</td>', 'Sara, so glad that you decided to enter this one. I love it!', '2010-04-26 01:21:44.000000', NULL, 1),
(5969842, 872305, 96751, '<td valign="top">Gorgeous!  Incredible mood.  Fave and would be surprised if front page.</td>', 'Gorgeous!  Incredible mood.  Fave and would be surprised if front page.', '2010-04-26 01:25:56.000000', NULL, 1),
(5969848, 873421, 96751, '<td valign="top">Very clean shot.</td>', 'Very clean shot.', '2010-04-26 01:26:45.000000', NULL, 1),
(5969855, 874174, 96751, '<td valign="top">Great texture.  The low branches make me want to see what is beyond them.  Nicely seen.</td>', 'Great texture.  The low branches make me want to see what is beyond them.  Nicely seen.', '2010-04-26 01:27:09.000000', NULL, 1),
(5969861, 873790, 96751, '<td valign="top">This looks like a marvelous place to meditate.</td>', 'This looks like a marvelous place to meditate.', '2010-04-26 01:27:33.000000', NULL, 1),
(5969864, 874167, 96751, '<td valign="top">Very sweet, although the child is almost invisible in the flowers.</td>', 'Very sweet, although the child is almost invisible in the flowers.', '2010-04-26 01:27:57.000000', NULL, 1),
(5969866, 874241, 96751, '<td valign="top">Love the road.  Where is this?</td>', 'Love the road.  Where is this?', '2010-04-26 01:28:11.000000', NULL, 1),
(5969868, 872066, 96751, '<td valign="top">Yeah.  Front page.</td>', 'Yeah.  Front page.', '2010-04-26 01:28:28.000000', NULL, 1),
(5969873, 872836, 96751, '<td valign="top">Stunning conversion.  The sky takes my breath away.  Front page.</td>', 'Stunning conversion.  The sky takes my breath away.  Front page.', '2010-04-26 01:29:18.000000', NULL, 1),
(5969877, 873647, 96751, '<td valign="top">So moody.</td>', 'So moody.', '2010-04-26 01:29:43.000000', NULL, 1),
(5969879, 873676, 15407, '<td valign="top">and cacti</td>', 'and cacti', '2010-04-26 01:30:01.000000', NULL, 1),
(5969881, 873624, 96751, '<td valign="top">Nice composition but there is a lack of highlights in the midtone range.</td>', 'Nice composition but there is a lack of highlights in the midtone range.', '2010-04-26 01:30:16.000000', NULL, 1),
(5969886, 872046, 96751, '<td valign="top">I just love birches.  And this sort of shot.  Front page, and a fave.</td>', 'I just love birches.  And this sort of shot.  Front page, and a fave.', '2010-04-26 01:30:54.000000', NULL, 1),
(5969889, 873278, 114219, '<td valign="top">I think this is a great photo....just seems overexposed.....6</td>', 'I think this is a great photo....just seems overexposed.....6', '2010-04-26 01:31:43.000000', NULL, 1),
(5969898, 873987, 96751, '<td valign="top">Love how the clouds look like rays.  Love the minimalist composition, although the trees look a bit blurry to me.</td>', 'Love how the clouds look like rays.  Love the minimalist composition, although the trees look a bit blurry to me.', '2010-04-26 01:32:31.000000', NULL, 1),
(5969901, 873814, 96751, '<td valign="top">There are so many strong elements in this shot, and I want to love it but it seems too busy for me.</td>', 'There are so many strong elements in this shot, and I want to love it but it seems too busy for me.', '2010-04-26 01:32:57.000000', NULL, 1),
(5969904, 873938, 114219, '<td valign="top">great photo, but I don''t see the landscape.....</td>', 'great photo, but I don''t see the landscape.....', '2010-04-26 01:33:10.000000', NULL, 1),
(5969906, 872309, 96751, '<td valign="top">Love the dew drops on the wire, and the mist on the far hill.  Very evocative image.</td>', 'Love the dew drops on the wire, and the mist on the far hill.  Very evocative image.', '2010-04-26 01:33:38.000000', NULL, 1),
(5969915, 872877, 60173, '<td valign="top">Thanks for using the name as the title, or it would have driven me nuts all week! That''s such an incredible structure. Nice tones and use of reflection.</td>', 'Thanks for using the name as the title, or it would have driven me nuts all week! That''s such an incredible structure. Nice tones and use of reflection.', '2010-04-26 01:34:21.000000', NULL, 1),
(5969921, 874127, 96751, '<td valign="top">This image confuses me - the sky is very dynamic but the trees and pasture to the left are very flat.</td>', 'This image confuses me - the sky is very dynamic but the trees and pasture to the left are very flat.', '2010-04-26 01:35:41.000000', NULL, 1),
(5969925, 872673, 96751, '<td valign="top">Great urban image.  Makes me a bit queasy though...</td>', 'Great urban image.  Makes me a bit queasy though...', '2010-04-26 01:36:24.000000', NULL, 1),
(5969927, 873857, 96751, '<td valign="top">Love the strong leading lines and the unconventional ties.</td>', 'Love the strong leading lines and the unconventional ties.', '2010-04-26 01:36:46.000000', NULL, 1),
(5969936, 873736, 96751, '<td valign="top">Love the processing on this, and how the cloud separation seems to mirror the stream, as though the stream parted them.  Incredible sky.</td>', 'Love the processing on this, and how the cloud separation seems to mirror the stream, as though the stream parted them.  Incredible sky.', '2010-04-26 01:37:37.000000', NULL, 1),
(5969954, 874280, 96751, '<td valign="top">Love the detail of the white, bare branches.  Frustrating that the light was not on the water, and caused such a harsh shadow to the right.</td>', 'Love the detail of the white, bare branches.  Frustrating that the light was not on the water, and caused such a harsh shadow to the right.', '2010-04-26 01:41:09.000000', NULL, 1),
(5969960, 873292, 96751, '<td valign="top">Love the perspective on this, and how the road and the delicate foliage breaks up the harsh geometry.  And the processing is top-notch.  Front page.</td>', 'Love the perspective on this, and how the road and the delicate foliage breaks up the harsh geometry.  And the processing is top-notch.  Front page.', '2010-04-26 01:42:23.000000', NULL, 1),
(5969988, 872066, 94614, '<td valign="top">love the shot, but the border is kind of disctracting. 8 anyway... good luck!</td>', 'love the shot, but the border is kind of disctracting. 8 anyway... good luck!', '2010-04-26 01:47:47.000000', NULL, 1),
(5970003, 874031, 94614, '<td valign="top">love the feel of this shot- makes me itch to get out hiking :)</td>', 'love the feel of this shot- makes me itch to get out hiking :)', '2010-04-26 01:51:19.000000', NULL, 1),
(5970007, 873312, 96751, '<td valign="top">Gorgeous place.  Incredible detail and tonal variations on the rocks, although the water in the lake looks rather dull by contrast.</td>', 'Gorgeous place.  Incredible detail and tonal variations on the rocks, although the water in the lake looks rather dull by contrast.', '2010-04-26 01:52:40.000000', NULL, 1),
(5970017, 873739, 30982, '<td valign="top">A quiet and somber view.  Nice detail in the buildings and a good flowing composition following along the diagonal.  The sky isn''t as dramatic as DPC likes to see skies, and while you perhaps could tease a bit more drama out of it in advanced editing, this is a solid presentation.</td>', 'A quiet and somber view.  Nice detail in the buildings and a good flowing composition following along the diagonal.  The sky isn''t as dramatic as DPC likes to see skies, and while you perhaps could tease a bit more drama out of it in advanced editing, this is a solid presentation.', '2010-04-26 01:55:07.000000', NULL, 1),
(5970021, 872877, 30982, '<td valign="top">Really like the silver tones to this - and what a lovely view of a lovely place!  For me, the negative space really adds to this.</td>', 'Really like the silver tones to this - and what a lovely view of a lovely place!  For me, the negative space really adds to this.', '2010-04-26 01:55:55.000000', NULL, 1),
(5970023, 873139, 30982, '<td valign="top">The composition really does lead me out to the pond as your title suggests.  Nicely seen from that perspective.  A bit "hazy" - was it toward the middle of the day?</td>', 'The composition really does lead me out to the pond as your title suggests.  Nicely seen from that perspective.  A bit "hazy" - was it toward the middle of the day?', '2010-04-26 01:57:30.000000', NULL, 1),
(5970024, 873995, 96751, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2010-04-26 01:57:39.000000', NULL, 1),
(5970029, 874245, 30982, '<td valign="top">My kind of shot, but perhaps not really a "landscape".  One tends to expect something a bit more sweeping, more encompassing.</td>', 'My kind of shot, but perhaps not really a "landscape".  One tends to expect something a bit more sweeping, more encompassing.', '2010-04-26 01:59:21.000000', NULL, 1),
(5970030, 874048, 96751, '<td valign="top">Never saw such a strong rainbow shot in b/w!  Awesome sky and capture.  I might have cropped a bit off the right, to the first big tree.</td>', 'Never saw such a strong rainbow shot in b/w!  Awesome sky and capture.  I might have cropped a bit off the right, to the first big tree.', '2010-04-26 01:59:28.000000', NULL, 1),
(5970032, 874199, 30982, '<td valign="top">I like the odd pairing of the two structures in this.  Good solid composition, pretty decent sky for "drama".</td>', 'I like the odd pairing of the two structures in this.  Good solid composition, pretty decent sky for "drama".', '2010-04-26 02:00:25.000000', NULL, 1),
(5970035, 874077, 96751, '<td valign="top">I hope someday to be able to create this effect in b/w. What conversion software do you use?  Front page.</td>', 'I hope someday to be able to create this effect in b/w. What conversion software do you use?  Front page.', '2010-04-26 02:01:17.000000', NULL, 1),
(5970036, 872022, 96751, '<td valign="top">Not a good day for the beach, but awesome for photography!</td>', 'Not a good day for the beach, but awesome for photography!', '2010-04-26 02:01:52.000000', NULL, 1),
(5970039, 873291, 30982, '<td valign="top">Very peaceful scene.  I like the light in the distance and you handled the exposure for this well.</td>', 'Very peaceful scene.  I like the light in the distance and you handled the exposure for this well.', '2010-04-26 02:02:49.000000', NULL, 1),
(5970040, 873877, 96751, '<td valign="top">Love, love, love it!  Might be over contrasted but works for me.  The fine line at the horizon really defines the space.</td>', 'Love, love, love it!  Might be over contrasted but works for me.  The fine line at the horizon really defines the space.', '2010-04-26 02:02:54.000000', NULL, 1),
(5970043, 873628, 96751, '<td valign="top">Love the processing - hope you''ll share in your notes.  I''d have cropped off about an inch on either end.</td>', 'Love the processing - hope you''ll share in your notes.  I''d have cropped off about an inch on either end.', '2010-04-26 02:03:29.000000', NULL, 1),
(5970046, 873182, 30982, '<td valign="top">Pretty good composition based on the rule of thirds and good use of the foreground.  The light strikes me as a bit harsh, though.</td>', 'Pretty good composition based on the rule of thirds and good use of the foreground.  The light strikes me as a bit harsh, though.', '2010-04-26 02:04:36.000000', NULL, 1),
(5970051, 873234, 96751, '<td valign="top">Not sure I like the green cast on this, but otherwise, this is such a stellar shot.  A bit dark but the sheep just slay me.  Front page.</td>', 'Not sure I like the green cast on this, but otherwise, this is such a stellar shot.  A bit dark but the sheep just slay me.  Front page.', '2010-04-26 02:06:02.000000', NULL, 1),
(5970054, 873144, 30982, '<td valign="top">Lovely detail in the bridge!  Nice night scene.</td>', 'Lovely detail in the bridge!  Nice night scene.', '2010-04-26 02:06:30.000000', NULL, 1),
(5970055, 874084, 106910, '<td valign="top">DNMC</td>', 'DNMC', '2010-04-26 02:06:44.000000', NULL, 1),
(5970058, 874106, 96751, '<td valign="top">The lines are really strong and the off=center road is a bit unconventional, but the image is a bit murky.</td>', 'The lines are really strong and the off=center road is a bit unconventional, but the image is a bit murky.', '2010-04-26 02:07:56.000000', NULL, 1),
(5970061, 873697, 30982, '<td valign="top">This to me is good use of B&amp;W.  I''d love to tell you why, but I think it''s mostly that the shades of gray seem so nicely balanced.  I do want to tilt the shot a bit to the right, though I do realize it is probably "straight". Probably too busy for some, but I like it well enough.</td>', 'This to me is good use of B&W.  I''d love to tell you why, but I think it''s mostly that the shades of gray seem so nicely balanced.  I do want to tilt the shot a bit to the right, though I do realize it is probably "straight". Probably too busy for some, but I like it well enough.', '2010-04-26 02:08:17.000000', NULL, 1),
(5970063, 873622, 49954, '<td valign="top">Floral, not landscape</td>', 'Floral, not landscape', '2010-04-26 02:09:11.000000', NULL, 1),
(5970064, 871851, 106910, '<td valign="top">DNMC</td>', 'DNMC', '2010-04-26 02:09:21.000000', NULL, 1),
(5970065, 873324, 30982, '<td valign="top">Sweeping and grand - and I''m assuming IR or a green channel conversion?  Nice detail.</td>', 'Sweeping and grand - and I''m assuming IR or a green channel conversion?  Nice detail.', '2010-04-26 02:09:36.000000', NULL, 1),
(5970067, 874186, 49954, '<td valign="top">Not enough context... pretty much a building shot.</td>', 'Not enough context... pretty much a building shot.', '2010-04-26 02:09:53.000000', NULL, 1),
(5970068, 872802, 96751, '<td valign="top">Incredible clarity and sharpness for a night shot.  Love the processing.  Front page.</td>', 'Incredible clarity and sharpness for a night shot.  Love the processing.  Front page.', '2010-04-26 02:09:57.000000', NULL, 1),
(5970069, 872401, 106910, '<td valign="top">DNMC</td>', 'DNMC', '2010-04-26 02:10:06.000000', NULL, 1),
(5970070, 874082, 30982, '<td valign="top">Makes me smile.  Not because he fell down, of course, but because it is a rather unique take on a "landscape".  I like the interpretation.</td>', 'Makes me smile.  Not because he fell down, of course, but because it is a rather unique take on a "landscape".  I like the interpretation.', '2010-04-26 02:10:23.000000', NULL, 1),
(5970072, 873646, 96751, '<td valign="top">Good contrast!</td>', 'Good contrast!', '2010-04-26 02:10:55.000000', NULL, 1),
(5970075, 873727, 112635, '<td valign="top">you got this in the bag! well done</td>', 'you got this in the bag! well done', '2010-04-26 02:11:49.000000', NULL, 1),
(5970076, 872576, 96751, '<td valign="top">Great processing.  The letterbox border really emphasizes the horizontal lines.  Fabulous tree.  Front page.</td>', 'Great processing.  The letterbox border really emphasizes the horizontal lines.  Fabulous tree.  Front page.', '2010-04-26 02:11:51.000000', NULL, 1),
(5970080, 873007, 96751, '<td valign="top">Nicely processed.</td>', 'Nicely processed.', '2010-04-26 02:12:37.000000', NULL, 1),
(5970083, 873344, 106910, '<td valign="top">It feels like it is falling to the right (photo is tilted). 5</td>', 'It feels like it is falling to the right (photo is tilted). 5', '2010-04-26 02:14:10.000000', NULL, 1),
(5970093, 872709, 116574, '<td valign="top">Love the juxtaposition in your picture of the strong black cows and and soft white buildings.  Interesting play of opposites.</td>', 'Love the juxtaposition in your picture of the strong black cows and and soft white buildings.  Interesting play of opposites.', '2010-04-26 02:17:13.000000', NULL, 1),
(5970102, 872653, 30982, '<td valign="top">Nice choice of a sweeping panorama with a nifty reflection!  I almost think I''d like it better without the framing on the right side (the tree).  You have the natural framing here on three sides, with the foreground and the trees, and it almost seems a bit fenced in to me.  But that''s just one opinion.</td>', 'Nice choice of a sweeping panorama with a nifty reflection!  I almost think I''d like it better without the framing on the right side (the tree).  You have the natural framing here on three sides, with the foreground and the trees, and it almost seems a bit fenced in to me.  But that''s just one opinion.', '2010-04-26 02:19:16.000000', NULL, 1),
(5970103, 873078, 30982, '<td valign="top">Nice choice and well photographed.</td>', 'Nice choice and well photographed.', '2010-04-26 02:19:30.000000', NULL, 1),
(5970108, 873903, 116574, '<td valign="top">The contrast is a bit too strong for my tastes but still like your picture.  I bet it''s beautiful and peaceful.</td>', 'The contrast is a bit too strong for my tastes but still like your picture.  I bet it''s beautiful and peaceful.', '2010-04-26 02:20:56.000000', NULL, 1),
(5970112, 874295, 30982, '<td valign="top">Very well titled!  Definitely expansive and lovely in B&amp;W.  Do I see windmills in the distance?  (Trying to figure what the little white posts are between cloud and ground.)</td>', 'Very well titled!  Definitely expansive and lovely in B&W.  Do I see windmills in the distance?  (Trying to figure what the little white posts are between cloud and ground.)', '2010-04-26 02:21:34.000000', NULL, 1),
(5970114, 874253, 30982, '<td valign="top">Wow - quite a stunning vista!  Very nice choice for B&amp;W, too.</td>', 'Wow - quite a stunning vista!  Very nice choice for B&W, too.', '2010-04-26 02:22:00.000000', NULL, 1),
(5970116, 873870, 96751, '<td valign="top">Nothing like old town rooftops!</td>', 'Nothing like old town rooftops!', '2010-04-26 02:22:29.000000', NULL, 1),
(5970117, 873569, 96751, '<td valign="top">Front page!!!</td>', 'Front page!!!', '2010-04-26 02:22:48.000000', NULL, 1),
(5970118, 874049, 96751, '<td valign="top">Good eye.</td>', 'Good eye.', '2010-04-26 02:23:09.000000', NULL, 1),
(5970119, 873113, 30982, '<td valign="top">I like how the people seem so small and insignificant compared to the approaching storm.  Something a bit funky with the processing, though.  I see a lot of blotchiness in the clouds and in the center portion of the water.  (I do have a monitor that is a bit on the bright side and does show artifacting when others may not see it.)</td>', 'I like how the people seem so small and insignificant compared to the approaching storm.  Something a bit funky with the processing, though.  I see a lot of blotchiness in the clouds and in the center portion of the water.  (I do have a monitor that is a bit on the bright side and does show artifacting when others may not see it.)', '2010-04-26 02:23:34.000000', NULL, 1),
(5970122, 874295, 96751, '<td valign="top">Big sky!  Stunning.  Front page.</td>', 'Big sky!  Stunning.  Front page.', '2010-04-26 02:24:41.000000', NULL, 1),
(5970123, 873810, 30982, '<td valign="top">Very nice detail in your cacti and rocks.  The wee wisps of clouds add a nice touch, too.  (Can''t quite figure the title, but that''s neither here nor there.)</td>', 'Very nice detail in your cacti and rocks.  The wee wisps of clouds add a nice touch, too.  (Can''t quite figure the title, but that''s neither here nor there.)', '2010-04-26 02:24:47.000000', NULL, 1),
(5970124, 873581, 15407, '<td valign="top">I''ld say "Over the bridge and into the City"</td>', 'I''ld say "Over the bridge and into the City"', '2010-04-26 02:24:59.000000', NULL, 1),
(5970125, 873879, 96751, '<td valign="top">I love the movement of this.</td>', 'I love the movement of this.', '2010-04-26 02:25:02.000000', NULL, 1),
(5970129, 874217, 96751, '<td valign="top">Oh, this just makes my stomach flip, even though it''s a great shot :-)</td>', 'Oh, this just makes my stomach flip, even though it''s a great shot :-)', '2010-04-26 02:27:21.000000', NULL, 1),
(5970131, 874202, 30982, '<td valign="top">Nice vista - shows how small a big city is in the scheme of things, doesn''t it?  Really lovely clouds in this.</td>', 'Nice vista - shows how small a big city is in the scheme of things, doesn''t it?  Really lovely clouds in this.', '2010-04-26 02:27:25.000000', NULL, 1),
(5970133, 872656, 96751, '<td valign="top">Strong architectural landscape.</td>', 'Strong architectural landscape.', '2010-04-26 02:27:50.000000', NULL, 1),
(5970134, 872994, 30982, '<td valign="top">Waterfalls tend to work very well in B&amp;W - this is certainly no exception.  Nicely done.</td>', 'Waterfalls tend to work very well in B&W - this is certainly no exception.  Nicely done.', '2010-04-26 02:27:50.000000', NULL, 1),
(5970138, 873697, 96751, '<td valign="top">Wonderful detail.</td>', 'Wonderful detail.', '2010-04-26 02:29:10.000000', NULL, 1),
(5970167, 873812, 62357, '<td valign="top">I love this.  It''s very well balanced.</td>', 'I love this.  It''s very well balanced.', '2010-04-26 02:37:24.000000', NULL, 1),
(5970171, 874194, 30982, '<td valign="top">Good solid city shot - with that one little bird!  A bit drab in B&amp;W - as though it struggles to find character on a gray day.</td>', 'Good solid city shot - with that one little bird!  A bit drab in B&W - as though it struggles to find character on a gray day.', '2010-04-26 02:38:13.000000', NULL, 1),
(5970173, 873970, 30982, '<td valign="top">Sweet!  Maybe not exactly what folks would consider a landscape, but I think it will do.</td>', 'Sweet!  Maybe not exactly what folks would consider a landscape, but I think it will do.', '2010-04-26 02:38:43.000000', NULL, 1),
(5970179, 873743, 30982, '<td valign="top">Almost has a 1950s feel to it, minus the slghtly more modern cars.  Interesting vantage point with nice use of leading lines and curves.</td>', 'Almost has a 1950s feel to it, minus the slghtly more modern cars.  Interesting vantage point with nice use of leading lines and curves.', '2010-04-26 02:40:23.000000', NULL, 1),
(5970182, 873622, 30982, '<td valign="top">I like the brightness of the foreground cacti - they translated well into B&amp;W for my tastes.  A bit more of a foliage closeup than a traditional landscape view perhaps.</td>', 'I like the brightness of the foreground cacti - they translated well into B&W for my tastes.  A bit more of a foliage closeup than a traditional landscape view perhaps.', '2010-04-26 02:41:21.000000', NULL, 1),
(5970185, 874297, 30982, '<td valign="top">An interesting and different interpretation!  I do like the rolling sidewalk.  Perhaps not a wide enough view to be a landscape to some, but I do like the different approach to this.  Nicely seen.</td>', 'An interesting and different interpretation!  I do like the rolling sidewalk.  Perhaps not a wide enough view to be a landscape to some, but I do like the different approach to this.  Nicely seen.', '2010-04-26 02:42:45.000000', NULL, 1),
(5970189, 872692, 30982, '<td valign="top">Translates very well into B&amp;W.  Lovely capture.</td>', 'Translates very well into B&W.  Lovely capture.', '2010-04-26 02:43:11.000000', NULL, 1),
(5970190, 873601, 30982, '<td valign="top">Striking clouds indeed and the whole scene translates well into monochrome.</td>', 'Striking clouds indeed and the whole scene translates well into monochrome.', '2010-04-26 02:43:38.000000', NULL, 1),
(5970194, 874282, 30982, '<td valign="top">The mountain has a very commanding presence!  I''m not sold on the centered composition, but I can''t tell you how to do it better, either.</td>', 'The mountain has a very commanding presence!  I''m not sold on the centered composition, but I can''t tell you how to do it better, either.', '2010-04-26 02:46:35.000000', NULL, 1),
(5970199, 872437, 30982, '<td valign="top">I like the bits of blown snow off the mountains - that''s pretty impressive!  I''m wondering if a conversion using a bit of a "green" filter would add a bit more life to your foreground evergreens.</td>', 'I like the bits of blown snow off the mountains - that''s pretty impressive!  I''m wondering if a conversion using a bit of a "green" filter would add a bit more life to your foreground evergreens.', '2010-04-26 02:47:46.000000', NULL, 1),
(5970200, 873727, 15407, '<td valign="top">I love that bridge!</td>', 'I love that bridge!', '2010-04-26 02:48:20.000000', NULL, 1),
(5970201, 873519, 30982, '<td valign="top">They look rather alien to me!  Pretty decent sky to show them off.</td>', 'They look rather alien to me!  Pretty decent sky to show them off.', '2010-04-26 02:48:42.000000', NULL, 1),
(5970202, 874079, 30982, '<td valign="top">Lovely pop from those poppies!  All of the elements work well together here, from the tree on the right (gorgeous thing) to the fench, to the bit of road on the far right.  Nicely composed, very good choice in conversion.</td>', 'Lovely pop from those poppies!  All of the elements work well together here, from the tree on the right (gorgeous thing) to the fench, to the bit of road on the far right.  Nicely composed, very good choice in conversion.', '2010-04-26 02:49:59.000000', NULL, 1),
(5970203, 873225, 30982, '<td valign="top">Solid composition but seems to lack a bit in crisp detail in the buildings across the way.  If at all possible, and it may not be, you may want to try this without the lit foreground on the right side and it does tend to pull the eye and really doesn''t contribute in my opinion.</td>', 'Solid composition but seems to lack a bit in crisp detail in the buildings across the way.  If at all possible, and it may not be, you may want to try this without the lit foreground on the right side and it does tend to pull the eye and really doesn''t contribute in my opinion.', '2010-04-26 02:51:38.000000', NULL, 1),
(5970205, 873054, 30982, '<td valign="top">Wow - must not be a good beach day (or must be really early!)  Great sky and almost a painterly feel to this.</td>', 'Wow - must not be a good beach day (or must be really early!)  Great sky and almost a painterly feel to this.', '2010-04-26 02:52:43.000000', NULL, 1),
(5970210, 874083, 30982, '<td valign="top">I like the idea behind this - nice timing.  The conversion looks a bit grainy - a hard shot to expose well since you have the sun versus the dark, shadowed trees.</td>', 'I like the idea behind this - nice timing.  The conversion looks a bit grainy - a hard shot to expose well since you have the sun versus the dark, shadowed trees.', '2010-04-26 02:57:47.000000', NULL, 1),
(5970211, 873742, 30982, '<td valign="top">Amazingly crisp and clear.  Would love to know how you achieved that!</td>', 'Amazingly crisp and clear.  Would love to know how you achieved that!', '2010-04-26 02:58:06.000000', NULL, 1),
(5970212, 873386, 30982, '<td valign="top">Nice use of IR - I love the foreground.</td>', 'Nice use of IR - I love the foreground.', '2010-04-26 02:58:38.000000', NULL, 1),
(5970215, 874239, 30982, '<td valign="top">I like your choice of portrait orientation for your landscape - works very well here!  Nicely balanced composition.  Perhaps a tad "blown" in the lower left corner of the water (on my monitor anyway).</td>', 'I like your choice of portrait orientation for your landscape - works very well here!  Nicely balanced composition.  Perhaps a tad "blown" in the lower left corner of the water (on my monitor anyway).', '2010-04-26 03:04:45.000000', NULL, 1),
