(5971209, 873033, 1024, '<td valign="top">This would have been perfect for Zen as well.  Nicely done.</td>', 'This would have been perfect for Zen as well.  Nicely done.', '2010-04-26 12:06:07.000000', NULL, 1),
(5971210, 872656, 73942, '<td valign="top">Nice contrast, which is key to B&amp;W.  Also has quite a bit of interest.  Nice and sharp without being too sharp.</td>', 'Nice contrast, which is key to B&W.  Also has quite a bit of interest.  Nice and sharp without being too sharp.', '2010-04-26 12:06:13.000000', NULL, 1),
(5971212, 872073, 68947, '<td valign="top">really lovely lighting and shadows!  I like the lightness of the background against the heavily contrasted foreground as it brings the eye to the foreground and subtly to the background area.  Nicely done</td>', 'really lovely lighting and shadows!  I like the lightness of the background against the heavily contrasted foreground as it brings the eye to the foreground and subtly to the background area.  Nicely done', '2010-04-26 12:06:18.000000', NULL, 1),
(5971216, 874250, 68947, '<td valign="top">Draws the eye into the middle of the shot.  Nicely done!</td>', 'Draws the eye into the middle of the shot.  Nicely done!', '2010-04-26 12:06:42.000000', NULL, 1),
(5971217, 872146, 1024, '<td valign="top">YES!!!!  This leaves me speechless, sorry the comment is not more elegant.</td>', 'YES!!!!  This leaves me speechless, sorry the comment is not more elegant.', '2010-04-26 12:07:04.000000', NULL, 1),
(5971218, 872877, 73942, '<td valign="top">wow - beautiful</td>', 'wow - beautiful', '2010-04-26 12:07:38.000000', NULL, 1),
(5971219, 872919, 68947, '<td valign="top">Interesting lines to the buildings.  Quite the mixture of horizontal to vertical and make the shot interesting, drawing the eye upwards with the angle you shot it from</td>', 'Interesting lines to the buildings.  Quite the mixture of horizontal to vertical and make the shot interesting, drawing the eye upwards with the angle you shot it from', '2010-04-26 12:07:51.000000', NULL, 1),
(5971221, 873226, 1024, '<td valign="top">I love the double leading lines, first the wooden stairs from the left and then the shore line from the right.  Nicely captured.</td>', 'I love the double leading lines, first the wooden stairs from the left and then the shore line from the right.  Nicely captured.', '2010-04-26 12:08:42.000000', NULL, 1),
(5971225, 874202, 1024, '<td valign="top">This may be the heart of the city but it is dwarfed by the massive border which does do the photo justice.</td>', 'This may be the heart of the city but it is dwarfed by the massive border which does do the photo justice.', '2010-04-26 12:10:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5971226, 874303, 68947, '<td valign="top">Seems a bit over-contrasted so that there''s blow-outs and not a lot of detail but, I like the way the water has picked up the light</td>', 'Seems a bit over-contrasted so that there''s blow-outs and not a lot of detail but, I like the way the water has picked up the light', '2010-04-26 12:10:15.000000', NULL, 1),
(5971229, 873660, 68947, '<td valign="top">Lots of great detail which is sadly lacking in a lot of other overly contrasted shots, making it a really interesting shot with a "feel" to it that is pleasing</td>', 'Lots of great detail which is sadly lacking in a lot of other overly contrasted shots, making it a really interesting shot with a "feel" to it that is pleasing', '2010-04-26 12:11:13.000000', NULL, 1),
(5971230, 874244, 1024, '<td valign="top">This is absolutely my favorite subject matter, old abandoned buildings.  Did you find yourself imagining the lives of the people who lived here years ago?</td>', 'This is absolutely my favorite subject matter, old abandoned buildings.  Did you find yourself imagining the lives of the people who lived here years ago?', '2010-04-26 12:11:27.000000', NULL, 1),
(5971232, 874050, 68947, '<td valign="top">I''m surprised that there''s really not many people walking around LOL.  But, very pretty shot!</td>', 'I''m surprised that there''s really not many people walking around LOL.  But, very pretty shot!', '2010-04-26 12:12:06.000000', NULL, 1),
(5971234, 873702, 68947, '<td valign="top">My fave place to take my camera!  And, look, the maid of the mist is running! :)  Lovely shot.  Very well done!</td>', 'My fave place to take my camera!  And, look, the maid of the mist is running! :)  Lovely shot.  Very well done!', '2010-04-26 12:12:50.000000', NULL, 1),
(5971237, 873991, 68947, '<td valign="top">Lovely shot and nicely done with the misty hills against the more defined foreground tree tops. :)</td>', 'Lovely shot and nicely done with the misty hills against the more defined foreground tree tops. :)', '2010-04-26 12:13:29.000000', NULL, 1),
(5971240, 872066, 68947, '<td valign="top">Very pretty and even the border works extremely well with this!</td>', 'Very pretty and even the border works extremely well with this!', '2010-04-26 12:13:53.000000', NULL, 1),
(5971242, 873887, 68947, '<td valign="top">Lovely city scape!  Nicely shot and edited. :)</td>', 'Lovely city scape!  Nicely shot and edited. :)', '2010-04-26 12:14:19.000000', NULL, 1),
(5971244, 873013, 68947, '<td valign="top">Strangely, this works really well!  There''s not a lot to it but, I think it''s the simpleness of the composition with the fence as a leading line that really makes it :)</td>', 'Strangely, this works really well!  There''s not a lot to it but, I think it''s the simpleness of the composition with the fence as a leading line that really makes it :)', '2010-04-26 12:15:28.000000', NULL, 1),
(5971246, 873888, 68947, '<td valign="top">So, I guess this is a rural, skyscape? :)  Nicely done!</td>', 'So, I guess this is a rural, skyscape? :)  Nicely done!', '2010-04-26 12:16:11.000000', NULL, 1),
(5971248, 874230, 68947, '<td valign="top">great cloud formation in this shot.  Love the heaviness of them over the land which seems to have a bit of sun poking through.</td>', 'great cloud formation in this shot.  Love the heaviness of them over the land which seems to have a bit of sun poking through.', '2010-04-26 12:17:06.000000', NULL, 1),
(5971249, 873405, 68947, '<td valign="top">the textures are contrasting which makes it very interesting</td>', 'the textures are contrasting which makes it very interesting', '2010-04-26 12:17:44.000000', NULL, 1),
(5971250, 873093, 68947, '<td valign="top">Not so sure about the clouds and processing because the clouds make it look grainy but, it''s a really gorgeous shot!</td>', 'Not so sure about the clouds and processing because the clouds make it look grainy but, it''s a really gorgeous shot!', '2010-04-26 12:18:44.000000', NULL, 1),
(5971251, 874153, 68947, '<td valign="top">A little too over processed and blown out but, has an artsy look to it</td>', 'A little too over processed and blown out but, has an artsy look to it', '2010-04-26 12:19:12.000000', NULL, 1),
(5971253, 874190, 68947, '<td valign="top">not a huge fan of the arc and slant but, the capture of the cloud reflection on the water is great :)</td>', 'not a huge fan of the arc and slant but, the capture of the cloud reflection on the water is great :)', '2010-04-26 12:19:46.000000', NULL, 1),
(5971255, 874121, 68947, '<td valign="top">I don''t generally take titles into consideration but, this one fits so nicely and gives it a "meaning" :)</td>', 'I don''t generally take titles into consideration but, this one fits so nicely and gives it a "meaning" :)', '2010-04-26 12:20:35.000000', NULL, 1),
(5971257, 872216, 68947, '<td valign="top">It may be a little over contrasted but, it gives a nice shape to the setting sun and the clouds</td>', 'It may be a little over contrasted but, it gives a nice shape to the setting sun and the clouds', '2010-04-26 12:21:21.000000', NULL, 1),
(5971260, 873676, 49954, '<td valign="top">Barely a landscape, since the rock is primary and you cannot see much behind it, but decently shot.</td>', 'Barely a landscape, since the rock is primary and you cannot see much behind it, but decently shot.', '2010-04-26 12:22:19.000000', NULL, 1),
(5971261, 874092, 68947, '<td valign="top">Very artsy.  I like it.  Just not sure that I''d consider this a "landscape" shot and it may score lower because people are taking a literal view of landscape.  :)</td>', 'Very artsy.  I like it.  Just not sure that I''d consider this a "landscape" shot and it may score lower because people are taking a literal view of landscape.  :)', '2010-04-26 12:22:19.000000', NULL, 1),
(5971262, 873759, 49954, '<td valign="top">Most uncreative title, but no penalty there...  Would like more detail in the sky</td>', 'Most uncreative title, but no penalty there...  Would like more detail in the sky', '2010-04-26 12:22:41.000000', NULL, 1),
(5971264, 872952, 49954, '<td valign="top">The clouds prepare for battle...</td>', 'The clouds prepare for battle...', '2010-04-26 12:22:57.000000', NULL, 1),
(5971266, 872309, 1024, '<td valign="top">What absolutely lovely early morning light.  You have captured the beauty of the early part of the day.</td>', 'What absolutely lovely early morning light.  You have captured the beauty of the early part of the day.', '2010-04-26 12:24:49.000000', NULL, 1),
(5971267, 873698, 1024, '<td valign="top">Breathtaking.</td>', 'Breathtaking.', '2010-04-26 12:25:09.000000', NULL, 1),
(5971270, 873433, 1024, '<td valign="top">I have seen more roads just like this than I can count. Thanks for the memories.</td>', 'I have seen more roads just like this than I can count. Thanks for the memories.', '2010-04-26 12:26:18.000000', NULL, 1),
(5971271, 874205, 1024, '<td valign="top">You get an extra point for the smile this gave me.</td>', 'You get an extra point for the smile this gave me.', '2010-04-26 12:26:46.000000', NULL, 1),
(5971272, 873239, 1024, '<td valign="top">Breathtaking!</td>', 'Breathtaking!', '2010-04-26 12:27:06.000000', NULL, 1),
(5971274, 872022, 1024, '<td valign="top">This takes me right back to my childhood and those summer storms on the beach.</td>', 'This takes me right back to my childhood and those summer storms on the beach.', '2010-04-26 12:28:01.000000', NULL, 1),
(5971278, 873296, 1024, '<td valign="top">This subject matter is not quite interesting enough to hold my attention for very long.</td>', 'This subject matter is not quite interesting enough to hold my attention for very long.', '2010-04-26 12:29:04.000000', NULL, 1),
(5971280, 872877, 114225, '<td valign="top">Excellently composed. It feels like a magical place straight out of a movie.</td>', 'Excellently composed. It feels like a magical place straight out of a movie.', '2010-04-26 12:29:17.000000', NULL, 1),
(5971283, 872708, 114225, '<td valign="top">A really nice scene. I like the contrast chosen.</td>', 'A really nice scene. I like the contrast chosen.', '2010-04-26 12:30:14.000000', NULL, 1),
(5971285, 873674, 1024, '<td valign="top">This is a very interesting shot, makes me want to explore the area more.  That is perhaps the greatest compliment, wanting to see more.</td>', 'This is a very interesting shot, makes me want to explore the area more.  That is perhaps the greatest compliment, wanting to see more.', '2010-04-26 12:30:53.000000', NULL, 1),
(5971286, 871817, 7504, '<td valign="top">It feels like the horizon is slightly off to me.</td>', 'It feels like the horizon is slightly off to me.', '2010-04-26 12:31:09.000000', NULL, 1),
(5971287, 873698, 114225, '<td valign="top">Wow, the small part of this view we can see is breathtaking, I can only try to imagine what the 360 view looks like.</td>', 'Wow, the small part of this view we can see is breathtaking, I can only try to imagine what the 360 view looks like.', '2010-04-26 12:31:13.000000', NULL, 1),
(5971288, 873656, 7504, '<td valign="top">This is gentle and lovely.</td>', 'This is gentle and lovely.', '2010-04-26 12:31:25.000000', NULL, 1),
(5971289, 871297, 114225, '<td valign="top">Great even-ness to this photo with the tallest trees on either side of the photo. That adds a lot of depth.</td>', 'Great even-ness to this photo with the tallest trees on either side of the photo. That adds a lot of depth.', '2010-04-26 12:31:49.000000', NULL, 1),
(5971290, 873739, 114225, '<td valign="top">Cool scene. I really like it, and think I would like it even more if it were brighter (to see more detail).</td>', 'Cool scene. I really like it, and think I would like it even more if it were brighter (to see more detail).', '2010-04-26 12:32:39.000000', NULL, 1),
(5971291, 872532, 7504, '<td valign="top">This seems more macro than landscape to me. Do like the backlit flowers though.</td>', 'This seems more macro than landscape to me. Do like the backlit flowers though.', '2010-04-26 12:32:52.000000', NULL, 1),
(5971292, 872854, 7504, '<td valign="top">LOVE the clouds.</td>', 'LOVE the clouds.', '2010-04-26 12:33:09.000000', NULL, 1),
(5971293, 873007, 1024, '<td valign="top">Nice use of the full tonal range.  Really rich blacks and pristine whites.</td>', 'Nice use of the full tonal range.  Really rich blacks and pristine whites.', '2010-04-26 12:33:20.000000', NULL, 1),
(5971295, 873912, 114225, '<td valign="top">Classic landscape. Well done.</td>', 'Classic landscape. Well done.', '2010-04-26 12:33:31.000000', NULL, 1),
(5971296, 873725, 7504, '<td valign="top">This might benefit from a little lightening.</td>', 'This might benefit from a little lightening.', '2010-04-26 12:33:42.000000', NULL, 1),
(5971299, 873886, 114225, '<td valign="top">Cool vantage point. I feel like I could reach up and touch those black clouds.</td>', 'Cool vantage point. I feel like I could reach up and touch those black clouds.', '2010-04-26 12:34:01.000000', NULL, 1),
(5971300, 874186, 7504, '<td valign="top">A bit over contrasted for me.</td>', 'A bit over contrasted for me.', '2010-04-26 12:34:03.000000', NULL, 1),
(5971302, 873709, 114225, '<td valign="top">Nicely lit scene. those long shadows add a lot of depth, and the clouds are really nice for this scene.</td>', 'Nicely lit scene. those long shadows add a lot of depth, and the clouds are really nice for this scene.', '2010-04-26 12:34:35.000000', NULL, 1),
(5971304, 872369, 7504, '<td valign="top">This is lovely.</td>', 'This is lovely.', '2010-04-26 12:35:05.000000', NULL, 1),
(5971305, 872692, 7504, '<td valign="top">NICE!</td>', 'NICE!', '2010-04-26 12:35:16.000000', NULL, 1),
(5971307, 872576, 7504, '<td valign="top">Love the tree!</td>', 'Love the tree!', '2010-04-26 12:35:31.000000', NULL, 1),
(5971308, 873584, 114225, '<td valign="top">That''s a great way to look at the waterfall. You don''t see this type of perspective often.</td>', 'That''s a great way to look at the waterfall. You don''t see this type of perspective often.', '2010-04-26 12:35:35.000000', NULL, 1),
(5971310, 872020, 114225, '<td valign="top">Very cool. I like how the misty mountains add a bit of story to it.</td>', 'Very cool. I like how the misty mountains add a bit of story to it.', '2010-04-26 12:36:19.000000', NULL, 1),
(5971311, 872653, 114225, '<td valign="top">Great photo. Well framed and nice job capturing perfectly calm water.</td>', 'Great photo. Well framed and nice job capturing perfectly calm water.', '2010-04-26 12:36:51.000000', NULL, 1),
(5971312, 873012, 7504, '<td valign="top">I love the curvy line leading to the island.</td>', 'I love the curvy line leading to the island.', '2010-04-26 12:37:22.000000', NULL, 1),
(5971313, 874089, 96751, '<td valign="top">I think the weeds in the foreground diminish the grandeur of the scene.</td>', 'I think the weeds in the foreground diminish the grandeur of the scene.', '2010-04-26 12:37:39.000000', NULL, 1),
(5971315, 872625, 7504, '<td valign="top">Seems a little too much contrast. The bridge is too dark and the sky to blown-out. The water looks beautiful.</td>', 'Seems a little too much contrast. The bridge is too dark and the sky to blown-out. The water looks beautiful.', '2010-04-26 12:39:20.000000', NULL, 1),
(5971316, 874044, 7504, '<td valign="top">The focus seem s abit soft.</td>', 'The focus seem s abit soft.', '2010-04-26 12:39:42.000000', NULL, 1),
(5971317, 872179, 96751, '<td valign="top">This looks like a stage set!  Gorgeous.  Front page.</td>', 'This looks like a stage set!  Gorgeous.  Front page.', '2010-04-26 12:39:47.000000', NULL, 1),
(5971318, 873676, 96751, '<td valign="top">Love the lighting and the processing on this.  Front page.</td>', 'Love the lighting and the processing on this.  Front page.', '2010-04-26 12:39:58.000000', NULL, 1),
(5971319, 874261, 96751, '<td valign="top">Love the symmetry.</td>', 'Love the symmetry.', '2010-04-26 12:40:05.000000', NULL, 1),
(5971320, 873405, 96751, '<td valign="top">Great reflection.</td>', 'Great reflection.', '2010-04-26 12:40:29.000000', NULL, 1),
(5971322, 873832, 7504, '<td valign="top">This is nice. I''ll be the color version is nice with the blossoming trees.</td>', 'This is nice. I''ll be the color version is nice with the blossoming trees.', '2010-04-26 12:40:40.000000', NULL, 1),
(5971325, 873616, 7504, '<td valign="top">I love the reflection of the swan. I wish there was something in the sky to give it more interest.</td>', 'I love the reflection of the swan. I wish there was something in the sky to give it more interest.', '2010-04-26 12:41:20.000000', NULL, 1),
(5971326, 873742, 96751, '<td valign="top">Exceptional clarity!</td>', 'Exceptional clarity!', '2010-04-26 12:41:21.000000', NULL, 1),
(5971327, 872146, 96751, '<td valign="top">Been there!  Very dramatic shot!  Nice counterpoint with the rocks in the foreground.</td>', 'Been there!  Very dramatic shot!  Nice counterpoint with the rocks in the foreground.', '2010-04-26 12:41:27.000000', NULL, 1),
(5971329, 873702, 7504, '<td valign="top">This is dramatic!</td>', 'This is dramatic!', '2010-04-26 12:42:15.000000', NULL, 1),
(5971330, 873183, 114225, '<td valign="top">Cool take on the challenge.</td>', 'Cool take on the challenge.', '2010-04-26 12:42:30.000000', NULL, 1),
(5971331, 872599, 114225, '<td valign="top">Good scene and nice use of contrast.</td>', 'Good scene and nice use of contrast.', '2010-04-26 12:42:50.000000', NULL, 1),
(5971332, 873755, 7504, '<td valign="top">This might benefit from a little more contrast.</td>', 'This might benefit from a little more contrast.', '2010-04-26 12:43:00.000000', NULL, 1),
(5971333, 873242, 114225, '<td valign="top">Excellent title for this photograph. Cool photo too :)</td>', 'Excellent title for this photograph. Cool photo too :)', '2010-04-26 12:43:15.000000', NULL, 1),
