(5971335, 873742, 114225, '<td valign="top">Nice job with creating a sharp nightscape.</td>', 'Nice job with creating a sharp nightscape.', '2010-04-26 12:44:03.000000', NULL, 1),
(5971336, 873263, 7504, '<td valign="top">I would love a postcard of this.</td>', 'I would love a postcard of this.', '2010-04-26 12:44:08.000000', NULL, 1),
(5971338, 873386, 96751, '<td valign="top">I love the processing on this!  Infrared setting?</td>', 'I love the processing on this!  Infrared setting?', '2010-04-26 12:44:37.000000', NULL, 1),
(5971339, 872146, 114225, '<td valign="top">This is a cool photo. I do with the rocks in front weren''t so prominent, they steal a lot of the ruin''s thunder.</td>', 'This is a cool photo. I do with the rocks in front weren''t so prominent, they steal a lot of the ruin''s thunder.', '2010-04-26 12:44:39.000000', NULL, 1),
(5971340, 873601, 7504, '<td valign="top">A bit over sharpened maybe? The sky is very dramatic!</td>', 'A bit over sharpened maybe? The sky is very dramatic!', '2010-04-26 12:44:47.000000', NULL, 1),
(5971341, 872022, 7504, '<td valign="top">This is so nice.</td>', 'This is so nice.', '2010-04-26 12:45:05.000000', NULL, 1),
(5971342, 873767, 114225, '<td valign="top">Very cool overhead shot. Nice shadows. I just wonder if it could be extended out a bit, to get a bit more depth.</td>', 'Very cool overhead shot. Nice shadows. I just wonder if it could be extended out a bit, to get a bit more depth.', '2010-04-26 12:45:19.000000', NULL, 1),
(5971346, 874184, 7504, '<td valign="top">Very pretty and clean. Nice.</td>', 'Very pretty and clean. Nice.', '2010-04-26 12:45:33.000000', NULL, 1),
(5971351, 872656, 114225, '<td valign="top">This is really cool, it does look like it comes from the game. IS that a blimp in the sky?</td>', 'This is really cool, it does look like it comes from the game. IS that a blimp in the sky?', '2010-04-26 12:46:38.000000', NULL, 1),
(5971353, 873767, 7504, '<td valign="top">Very cool perspective. Maybe over sharpened?</td>', 'Very cool perspective. Maybe over sharpened?', '2010-04-26 12:47:03.000000', NULL, 1),
(5971355, 873684, 114225, '<td valign="top">Nice job catching the sun just peeking over the trees in the horizon.</td>', 'Nice job catching the sun just peeking over the trees in the horizon.', '2010-04-26 12:48:08.000000', NULL, 1),
(5971357, 872884, 114225, '<td valign="top">What a great place to have a home/cottage.</td>', 'What a great place to have a home/cottage.', '2010-04-26 12:48:28.000000', NULL, 1),
(5971361, 873820, 114225, '<td valign="top">This is a cool scene. I''m just not sure how i feel about the leaves all being bright white. Certainly makes the old building stand out more.</td>', 'This is a cool scene. I''m just not sure how i feel about the leaves all being bright white. Certainly makes the old building stand out more.', '2010-04-26 12:49:34.000000', NULL, 1),
(5971362, 872548, 96751, '<td valign="top">Did yo use a star filter on this?  Beautiful details</td>', 'Did yo use a star filter on this?  Beautiful details', '2010-04-26 12:49:36.000000', NULL, 1),
(5971364, 874102, 96751, '<td valign="top">I like the movement in this.</td>', 'I like the movement in this.', '2010-04-26 12:49:55.000000', NULL, 1),
(5971365, 872371, 116489, '<td valign="top">Rating this low because it seems too dark to me, not enough contrast.  The trees in the middle of the picture are just dark blobs.  Nice composition, but would have been better to shoot during the day.</td>', 'Rating this low because it seems too dark to me, not enough contrast.  The trees in the middle of the picture are just dark blobs.  Nice composition, but would have been better to shoot during the day.', '2010-04-26 12:49:58.000000', NULL, 1),
(5971367, 873889, 114225, '<td valign="top">I like the idea of this one. It feels kind of HDRish (Topaz?) which gives it an unnatural feel.</td>', 'I like the idea of this one. It feels kind of HDRish (Topaz?) which gives it an unnatural feel.', '2010-04-26 12:50:22.000000', NULL, 1),
(5971372, 873773, 96751, '<td valign="top">THAT''s a house with a view!  Wow.</td>', 'THAT''s a house with a view!  Wow.', '2010-04-26 12:50:55.000000', NULL, 1),
(5971373, 874254, 1024, '<td valign="top">What beautiful rugged landscape.  Your photo does it justice.  6</td>', 'What beautiful rugged landscape.  Your photo does it justice.  6', '2010-04-26 12:51:11.000000', NULL, 1),
(5971374, 872802, 114225, '<td valign="top">Nice photo. I like what you were going for with the framing, but the object on the right side almost takes up too much of the photograph.</td>', 'Nice photo. I like what you were going for with the framing, but the object on the right side almost takes up too much of the photograph.', '2010-04-26 12:51:19.000000', NULL, 1),
(5971376, 873671, 116489, '<td valign="top">The plane might have added interest to this shot if it was entirely in the frame and in focus, but as it is, it just distracts from the skyline.</td>', 'The plane might have added interest to this shot if it was entirely in the frame and in focus, but as it is, it just distracts from the skyline.', '2010-04-26 12:51:33.000000', NULL, 1),
(5971380, 873581, 114225, '<td valign="top">Nice attempt at getting the moon with the city. I don''t like how the moon is overly bright from the long exposure. I wonder if a graduated ND filter could have helped out.</td>', 'Nice attempt at getting the moon with the city. I don''t like how the moon is overly bright from the long exposure. I wonder if a graduated ND filter could have helped out.', '2010-04-26 12:52:25.000000', NULL, 1),
