(5971701, 872244, 1024, '<td valign="top">Those wires are going to kill you.  Basic editing is realy hard after you get used to advanced.</td>', 'Those wires are going to kill you.  Basic editing is realy hard after you get used to advanced.', '2010-04-26 15:00:38.000000', NULL, 1),
(5971705, 873590, 1024, '<td valign="top">There are some photos that just need to be in color.  This may be one of them.</td>', 'There are some photos that just need to be in color.  This may be one of them.', '2010-04-26 15:01:18.000000', NULL, 1),
(5971706, 873936, 1024, '<td valign="top">Old mills are such a wonderful subject in any fashion, but especially nice in black and white.</td>', 'Old mills are such a wonderful subject in any fashion, but especially nice in black and white.', '2010-04-26 15:02:08.000000', NULL, 1),
(5971708, 873590, 10785, '<td valign="top">Very good technical elements here with a strong shape compositionally, excellent textures with the grasses and good lighting giving depth. What''s missing in this particular view is some layers (i.e. foreground, midground, background). I know the flowers are in the foreground but they just do not stand out enough against the grasses. It needs a tall object or something else to help it out.</td>', 'Very good technical elements here with a strong shape compositionally, excellent textures with the grasses and good lighting giving depth. What''s missing in this particular view is some layers (i.e. foreground, midground, background). I know the flowers are in the foreground but they just do not stand out enough against the grasses. It needs a tall object or something else to help it out.', '2010-04-26 15:02:56.000000', NULL, 1),
(5971718, 871297, 109614, '<td valign="top">Very nice shot!  Detail and sharpness are excellent.</td>', 'Very nice shot!  Detail and sharpness are excellent.', '2010-04-26 15:07:54.000000', NULL, 1),
