(5971730, 873625, 1024, '<td valign="top">This is perfection.</td>', 'This is perfection.', '2010-04-26 15:13:27.000000', NULL, 1),
(5971734, 872020, 75585, '<td valign="top">I really like this - my only fault with it is the tilting down on the left.  For  me it is really important to have level horizons the shoreline on this is drastically low to the left.</td>', 'I really like this - my only fault with it is the tilting down on the left.  For  me it is really important to have level horizons the shoreline on this is drastically low to the left.', '2010-04-26 15:15:33.000000', NULL, 1),
(5971740, 873646, 62357, '<td valign="top">This is lovely but does feel a tad over sharpened to my eyes.</td>', 'This is lovely but does feel a tad over sharpened to my eyes.', '2010-04-26 15:16:00.000000', NULL, 1),
(5971741, 871850, 75585, '<td valign="top">Very nice shot &lt;not voting&gt;</td>', 'Very nice shot <not voting>', '2010-04-26 15:16:08.000000', NULL, 1),
