(5972239, 872802, 95579, '<td valign="top">Really pretty urban scene</td>', 'Really pretty urban scene', '2010-04-26 18:15:04.000000', NULL, 1),
(5972241, 873857, 95579, '<td valign="top">Love the abandoned feling of this</td>', 'Love the abandoned feling of this', '2010-04-26 18:15:28.000000', NULL, 1),
(5972244, 873240, 95579, '<td valign="top">I like the balance of the different sections</td>', 'I like the balance of the different sections', '2010-04-26 18:16:11.000000', NULL, 1),
(5972245, 873697, 61396, '<td valign="top">Nice reflection.I am not sure I understand what this black triangle is. (not voting).</td>', 'Nice reflection.I am not sure I understand what this black triangle is. (not voting).', '2010-04-26 18:16:11.000000', NULL, 1),
(5972261, 873176, 61396, '<td valign="top">It is nice how you got those sticks to hold the clouds in place. (not voting)</td>', 'It is nice how you got those sticks to hold the clouds in place. (not voting)', '2010-04-26 18:21:31.000000', NULL, 1),
(5972264, 873858, 76335, '<td valign="top">(1/38) The sky is beautiful, but I''m especially struck by the sweeping fence which grabs the viewer''s eye in the foreground and catapults it past the tree and into the barn. Wonderful panoramic scene.</td>', '(1/38) The sky is beautiful, but I''m especially struck by the sweeping fence which grabs the viewer''s eye in the foreground and catapults it past the tree and into the barn. Wonderful panoramic scene.', '2010-04-26 18:22:15.000000', NULL, 1),
(5972266, 873624, 76335, '<td valign="top">(2/38) Very nice. I like the tire tracks, and leading lines. I think it can be sharper.</td>', '(2/38) Very nice. I like the tire tracks, and leading lines. I think it can be sharper.', '2010-04-26 18:22:23.000000', NULL, 1),
(5972271, 871851, 76335, '<td valign="top">(3/38) A grand looking landmark, but I''m having trouble calling this a landscape.</td>', '(3/38) A grand looking landmark, but I''m having trouble calling this a landscape.', '2010-04-26 18:24:19.000000', NULL, 1),
(5972276, 872237, 76335, '<td valign="top">(4/38) I like the gritty textures, and the composition is nicely balanced.</td>', '(4/38) I like the gritty textures, and the composition is nicely balanced.', '2010-04-26 18:26:22.000000', NULL, 1),
(5972281, 874284, 35513, '<td valign="top">Nice leading lines in this shot!  Very lovely composition.</td>', 'Nice leading lines in this shot!  Very lovely composition.', '2010-04-26 18:27:43.000000', NULL, 1),
(5972282, 872022, 76335, '<td valign="top">(5/38) The lighthouse is fittingly placed between the threatening sky and windblown land.</td>', '(5/38) The lighthouse is fittingly placed between the threatening sky and windblown land.', '2010-04-26 18:27:48.000000', NULL, 1),
(5972283, 872315, 35513, '<td valign="top">The B&amp;W tones here are wonderful!!  Love this shot!</td>', 'The B&W tones here are wonderful!!  Love this shot!', '2010-04-26 18:28:02.000000', NULL, 1),
(5972284, 873625, 35513, '<td valign="top">There seems to be a bit of a halo above the skyline, but I like the little "peek" this photo gives of the city.</td>', 'There seems to be a bit of a halo above the skyline, but I like the little "peek" this photo gives of the city.', '2010-04-26 18:28:34.000000', NULL, 1),
(5972288, 874239, 35513, '<td valign="top">I like the perspective on this shot!  You''re probably getting some comments about the highlights in the tree and the forefront of the waterfall being a bit blown out....what can you do sometimes?  Someday someone will put a helpful dial on the sun for us photographers! :-)</td>', 'I like the perspective on this shot!  You''re probably getting some comments about the highlights in the tree and the forefront of the waterfall being a bit blown out....what can you do sometimes?  Someday someone will put a helpful dial on the sun for us photographers! :-)', '2010-04-26 18:29:44.000000', NULL, 1),
(5972291, 873225, 35513, '<td valign="top">I really like how the city is silhouetted against the sky!  The light in the lower right corner is a bit distracting...headlights?  Overall though, a nice shot!</td>', 'I really like how the city is silhouetted against the sky!  The light in the lower right corner is a bit distracting...headlights?  Overall though, a nice shot!', '2010-04-26 18:30:32.000000', NULL, 1),
(5972293, 873411, 35513, '<td valign="top">The starkness of this shot is really neat, and I think works very well for B&amp;W.</td>', 'The starkness of this shot is really neat, and I think works very well for B&W.', '2010-04-26 18:30:59.000000', NULL, 1),
(5972296, 872437, 76335, '<td valign="top">(6/38) I like the contrast of the dark shadows against the glaring reflection of the peaks.</td>', '(6/38) I like the contrast of the dark shadows against the glaring reflection of the peaks.', '2010-04-26 18:31:46.000000', NULL, 1),
(5972297, 873013, 35513, '<td valign="top">Great clouds and I like the line of pines in the background!  For me, I probably would have started the composition with the fence rather than the tree on the left.  I think the fence and trees create some nice lines.</td>', 'Great clouds and I like the line of pines in the background!  For me, I probably would have started the composition with the fence rather than the tree on the left.  I think the fence and trees create some nice lines.', '2010-04-26 18:31:49.000000', NULL, 1),
(5972302, 872982, 35513, '<td valign="top">The path helps lead the eye through this shot and the B&amp;W tones look good</td>', 'The path helps lead the eye through this shot and the B&W tones look good', '2010-04-26 18:32:31.000000', NULL, 1),
(5972303, 873814, 76335, '<td valign="top">(7/38) I love all the gnarly lines...</td>', '(7/38) I love all the gnarly lines...', '2010-04-26 18:32:41.000000', NULL, 1),
(5972305, 873812, 35513, '<td valign="top">This is GORGEOUS!!  Such a beautiful scene that my eye sees it in color, even though it''s B&amp;W.  Lovely!</td>', 'This is GORGEOUS!!  Such a beautiful scene that my eye sees it in color, even though it''s B&W.  Lovely!', '2010-04-26 18:33:11.000000', NULL, 1),
(5972309, 872540, 35513, '<td valign="top">I love, love, love, the birds on the water here.  They come out so nicely!!  Beautiful composition as well.</td>', 'I love, love, love, the birds on the water here.  They come out so nicely!!  Beautiful composition as well.', '2010-04-26 18:33:52.000000', NULL, 1),
(5972310, 873886, 1024, '<td valign="top">Excellent capture</td>', 'Excellent capture', '2010-04-26 18:34:04.000000', NULL, 1),
(5972312, 873519, 36616, '<td valign="top">Love the sky, find the lower half bland</td>', 'Love the sky, find the lower half bland', '2010-04-26 18:34:25.000000', NULL, 1),
(5972314, 873736, 35513, '<td valign="top">Wow, what a great shot!!  Love the drama in the sky, love the way the stream leads the eye.  The texture of the grass comes out very nicely...plenty of interest!</td>', 'Wow, what a great shot!!  Love the drama in the sky, love the way the stream leads the eye.  The texture of the grass comes out very nicely...plenty of interest!', '2010-04-26 18:34:30.000000', NULL, 1),
(5972315, 872252, 1024, '<td valign="top">The ducks are just the crowning touch.</td>', 'The ducks are just the crowning touch.', '2010-04-26 18:34:35.000000', NULL, 1),
(5972316, 872457, 35513, '<td valign="top">The lighting here really makes the shot.  I like it more the more I look at it!</td>', 'The lighting here really makes the shot.  I like it more the more I look at it!', '2010-04-26 18:34:50.000000', NULL, 1),
(5972319, 873234, 1024, '<td valign="top">This is just too cute for words (but then I love sheep).</td>', 'This is just too cute for words (but then I love sheep).', '2010-04-26 18:35:11.000000', NULL, 1),
(5972320, 872599, 35513, '<td valign="top">Very nice reflection in the water!  The grey from the land/trees on the right is a bit distracting....though you have to frame the shot somehow!  I''d be curious to see the view shifted to the left.</td>', 'Very nice reflection in the water!  The grey from the land/trees on the right is a bit distracting....though you have to frame the shot somehow!  I''d be curious to see the view shifted to the left.', '2010-04-26 18:35:56.000000', NULL, 1),
(5972322, 873297, 35513, '<td valign="top">The B&amp;W tones here really emphasize the amazing texture in these rocks.  Well done!</td>', 'The B&W tones here really emphasize the amazing texture in these rocks.  Well done!', '2010-04-26 18:36:22.000000', NULL, 1),
(5972323, 873830, 1024, '<td valign="top">What is that dark thing on the side of the road?  My eye keeps coming back to it.... almost looks like a dead animal.</td>', 'What is that dark thing on the side of the road?  My eye keeps coming back to it.... almost looks like a dead animal.', '2010-04-26 18:36:24.000000', NULL, 1),
(5972324, 874106, 1024, '<td valign="top">... and it goes on forever.....</td>', '... and it goes on forever.....', '2010-04-26 18:36:44.000000', NULL, 1),
(5972325, 873991, 1024, '<td valign="top">I love this effect.</td>', 'I love this effect.', '2010-04-26 18:37:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5972326, 873405, 76335, '<td valign="top">(8/38) Beautiful, love the depth. Can''t imagine it looking any better in color.</td>', '(8/38) Beautiful, love the depth. Can''t imagine it looking any better in color.', '2010-04-26 18:37:20.000000', NULL, 1),
(5972327, 873755, 35513, '<td valign="top">Great scenery!  I feel this shot could perhaps benefit from a slight adjustment in Levels or Curves.  It was very possibly an overcast day, but having a little more range from black to white would really make this shot pop!</td>', 'Great scenery!  I feel this shot could perhaps benefit from a slight adjustment in Levels or Curves.  It was very possibly an overcast day, but having a little more range from black to white would really make this shot pop!', '2010-04-26 18:37:21.000000', NULL, 1),
(5972328, 874250, 35513, '<td valign="top">Now I miss the beach :-(  Love the waves rolling in!</td>', 'Now I miss the beach :-(  Love the waves rolling in!', '2010-04-26 18:37:42.000000', NULL, 1),
(5972330, 871765, 35513, '<td valign="top">This is really nice urban landscape!  Lots of visual interest and great composition....well done!</td>', 'This is really nice urban landscape!  Lots of visual interest and great composition....well done!', '2010-04-26 18:38:03.000000', NULL, 1),
(5972332, 874087, 35513, '<td valign="top">Nicely composed!  I would be curious to see this at an angle a little closer to the water.  I love the winding view of the water, but the trees are a little distracting for me.</td>', 'Nicely composed!  I would be curious to see this at an angle a little closer to the water.  I love the winding view of the water, but the trees are a little distracting for me.', '2010-04-26 18:39:21.000000', NULL, 1),
(5972335, 872748, 35513, '<td valign="top">Very dramatic lighting here!  Really makes the shot!</td>', 'Very dramatic lighting here!  Really makes the shot!', '2010-04-26 18:39:42.000000', NULL, 1),
(5972336, 873858, 35513, '<td valign="top">Oh, this is classic!  Great sky, great composition....plenty of range in B&amp;W tones.  So very well done!</td>', 'Oh, this is classic!  Great sky, great composition....plenty of range in B&W tones.  So very well done!', '2010-04-26 18:40:09.000000', NULL, 1),
(5972338, 872216, 35513, '<td valign="top">I like the way the rays of light from the sun are visible in the sky...though I''m not sure sunsets are the easiest thing to capture in B&amp;W.</td>', 'I like the way the rays of light from the sun are visible in the sky...though I''m not sure sunsets are the easiest thing to capture in B&W.', '2010-04-26 18:40:39.000000', NULL, 1),
(5972339, 871829, 35513, '<td valign="top">The way the rock and water play together in this shot is beautiful!</td>', 'The way the rock and water play together in this shot is beautiful!', '2010-04-26 18:40:56.000000', NULL, 1),
(5972340, 871850, 35513, '<td valign="top">This has a minimalistic feel to it that I really like :-)</td>', 'This has a minimalistic feel to it that I really like :-)', '2010-04-26 18:41:23.000000', NULL, 1),
(5972343, 874153, 35513, '<td valign="top">This looks like beautiful scenery, but much of it is lost in white....a little bit of gray would help bring out those details.  Maybe too much contrast?</td>', 'This looks like beautiful scenery, but much of it is lost in white....a little bit of gray would help bring out those details.  Maybe too much contrast?', '2010-04-26 18:42:19.000000', NULL, 1),
(5972344, 873936, 35513, '<td valign="top">Very scenic!</td>', 'Very scenic!', '2010-04-26 18:42:45.000000', NULL, 1),
(5972346, 873312, 35513, '<td valign="top">This looks like such a relaxing place!  Beautiful work on this waterfall!</td>', 'This looks like such a relaxing place!  Beautiful work on this waterfall!', '2010-04-26 18:43:07.000000', NULL, 1),
(5972349, 874098, 35513, '<td valign="top">I really like the perspective in this shot!</td>', 'I really like the perspective in this shot!', '2010-04-26 18:43:21.000000', NULL, 1),
(5972351, 873461, 35513, '<td valign="top">Was this done infrared?  Either way, I love the ivory look of the trees!</td>', 'Was this done infrared?  Either way, I love the ivory look of the trees!', '2010-04-26 18:43:47.000000', NULL, 1),
(5972352, 873904, 35513, '<td valign="top">This is just stunning!</td>', 'This is just stunning!', '2010-04-26 18:43:55.000000', NULL, 1),
(5972353, 873824, 35513, '<td valign="top">I like the lines created by the mountains, but the differences in gray are so subtle that they almost disappear.</td>', 'I like the lines created by the mountains, but the differences in gray are so subtle that they almost disappear.', '2010-04-26 18:44:22.000000', NULL, 1),
(5972354, 873280, 35513, '<td valign="top">I love the simplicity in this shot...well done!</td>', 'I love the simplicity in this shot...well done!', '2010-04-26 18:44:43.000000', NULL, 1),
(5972356, 873251, 35513, '<td valign="top">Very emotive!</td>', 'Very emotive!', '2010-04-26 18:45:03.000000', NULL, 1),
(5972357, 872179, 35513, '<td valign="top">This is pure lovely!</td>', 'This is pure lovely!', '2010-04-26 18:45:12.000000', NULL, 1),
(5972358, 874295, 35513, '<td valign="top">Wow, that sky is fantastic!!  Just amazing!</td>', 'Wow, that sky is fantastic!!  Just amazing!', '2010-04-26 18:45:36.000000', NULL, 1),
(5972359, 873332, 35513, '<td valign="top">This is so lovely!  I adore the detail in the roots and rocks at the base of the pic!</td>', 'This is so lovely!  I adore the detail in the roots and rocks at the base of the pic!', '2010-04-26 18:46:18.000000', NULL, 1),
(5972362, 873727, 35513, '<td valign="top">Oh.  Wow!  This is so cool!</td>', 'Oh.  Wow!  This is so cool!', '2010-04-26 18:46:51.000000', NULL, 1),
(5972364, 873773, 35513, '<td valign="top">What a view!</td>', 'What a view!', '2010-04-26 18:47:03.000000', NULL, 1),
(5972367, 872332, 35513, '<td valign="top">Lovely textures!!</td>', 'Lovely textures!!', '2010-04-26 18:48:12.000000', NULL, 1),
(5972368, 874097, 116489, '<td valign="top">I think this would have worked better if it had been darker, giving more contrast between the bales and the ground.</td>', 'I think this would have worked better if it had been darker, giving more contrast between the bales and the ground.', '2010-04-26 18:48:16.000000', NULL, 1),
(5972369, 873766, 1024, '<td valign="top">Great use of leading lines and the DOF is spot on.</td>', 'Great use of leading lines and the DOF is spot on.', '2010-04-26 18:48:24.000000', NULL, 1),
(5972372, 873768, 35513, '<td valign="top">This is so lovely!!  B&amp;W really works well here!</td>', 'This is so lovely!!  B&W really works well here!', '2010-04-26 18:49:01.000000', NULL, 1),
(5972373, 871765, 1024, '<td valign="top">I love this vantage point.  If this was in my city, I might have a new favorite photo spot.</td>', 'I love this vantage point.  If this was in my city, I might have a new favorite photo spot.', '2010-04-26 18:49:08.000000', NULL, 1),
(5972374, 873926, 35513, '<td valign="top">The background of this shot is really interesting....I might like it a hair better without the golfer.</td>', 'The background of this shot is really interesting....I might like it a hair better without the golfer.', '2010-04-26 18:49:37.000000', NULL, 1),
(5972375, 873421, 35513, '<td valign="top">Very nice!</td>', 'Very nice!', '2010-04-26 18:49:48.000000', NULL, 1),
(5972376, 873862, 35513, '<td valign="top">There''s almost a bit too much to look at here</td>', 'There''s almost a bit too much to look at here', '2010-04-26 18:50:16.000000', NULL, 1),
(5972377, 872305, 35513, '<td valign="top">Oh, this is so nicely done!!  Love the sky and lighting!</td>', 'Oh, this is so nicely done!!  Love the sky and lighting!', '2010-04-26 18:50:36.000000', NULL, 1),
(5972379, 873865, 35513, '<td valign="top">Very nice sense of depth in this shot!</td>', 'Very nice sense of depth in this shot!', '2010-04-26 18:50:55.000000', NULL, 1),
(5972381, 871851, 35513, '<td valign="top">Of all the cemetery shots on the site, this is one of the more dramatic ones, though I don''t feel it really fits the spirit of a Landscape challenge.</td>', 'Of all the cemetery shots on the site, this is one of the more dramatic ones, though I don''t feel it really fits the spirit of a Landscape challenge.', '2010-04-26 18:51:47.000000', NULL, 1),
(5972382, 872648, 116489, '<td valign="top">The greys in this seem flat to me.</td>', 'The greys in this seem flat to me.', '2010-04-26 18:51:53.000000', NULL, 1),
(5972383, 874062, 35513, '<td valign="top">Are these trees snowcovered?  Or is this infrared?  Very interesting effect....makes it look engraved!</td>', 'Are these trees snowcovered?  Or is this infrared?  Very interesting effect....makes it look engraved!', '2010-04-26 18:52:31.000000', NULL, 1),
(5972384, 873942, 116489, '<td valign="top">I think the placement of the boat here detracts from the composition. I would have waited until it was further to the right.</td>', 'I think the placement of the boat here detracts from the composition. I would have waited until it was further to the right.', '2010-04-26 18:52:41.000000', NULL, 1),
(5972387, 873234, 116489, '<td valign="top">The tinge of green doesn''t work for me, I''m afraid.</td>', 'The tinge of green doesn''t work for me, I''m afraid.', '2010-04-26 18:53:28.000000', NULL, 1),
(5972390, 873213, 116489, '<td valign="top">This is a nice shot, but sadly, the greys are very flat.</td>', 'This is a nice shot, but sadly, the greys are very flat.', '2010-04-26 18:54:23.000000', NULL, 1),
(5972392, 873020, 116489, '<td valign="top">The shallow depth of focus doesn''t work for me here; it just makes it seem like nothing at all is in focus.</td>', 'The shallow depth of focus doesn''t work for me here; it just makes it seem like nothing at all is in focus.', '2010-04-26 18:55:35.000000', NULL, 1),
(5972394, 872309, 35513, '<td valign="top">Wow, the lighting is so ethereal!</td>', 'Wow, the lighting is so ethereal!', '2010-04-26 18:56:02.000000', NULL, 1),
(5972395, 873328, 35513, '<td valign="top">Great capture!</td>', 'Great capture!', '2010-04-26 18:56:33.000000', NULL, 1),
(5972396, 873601, 1024, '<td valign="top">Very unique cloud formations.  I like the treatment you have given the sky.</td>', 'Very unique cloud formations.  I like the treatment you have given the sky.', '2010-04-26 18:57:18.000000', NULL, 1),
(5972398, 872576, 35513, '<td valign="top">Wow, this is stunning!!!  What an amazing tree and the sky is so dramatic!</td>', 'Wow, this is stunning!!!  What an amazing tree and the sky is so dramatic!', '2010-04-26 18:57:41.000000', NULL, 1),
(5972399, 871297, 73942, '<td valign="top">wow, great looking sky, it has great contrast</td>', 'wow, great looking sky, it has great contrast', '2010-04-26 18:57:53.000000', NULL, 1),
(5972401, 872369, 35513, '<td valign="top">Love the reflections!</td>', 'Love the reflections!', '2010-04-26 18:58:01.000000', NULL, 1),
(5972403, 874294, 1024, '<td valign="top">There is not much here to hold my interest for very long and your horizon is tilted ever so slightly.</td>', 'There is not much here to hold my interest for very long and your horizon is tilted ever so slightly.', '2010-04-26 18:58:26.000000', NULL, 1),
(5972405, 872146, 73942, '<td valign="top">nice lines in the ruins and the rocks are perfectly placed on the rule of thirds, well seen</td>', 'nice lines in the ruins and the rocks are perfectly placed on the rule of thirds, well seen', '2010-04-26 18:58:30.000000', NULL, 1),
(5972408, 873556, 73942, '<td valign="top">I''ve always loved solo tree shots, this one is even cooler cause you found one on a hill</td>', 'I''ve always loved solo tree shots, this one is even cooler cause you found one on a hill', '2010-04-26 18:59:10.000000', NULL, 1),
(5972409, 873144, 116489, '<td valign="top">I like this shot, but I would have liked it more with the tower on the right cropped out.  Its brightness draws the eye away from the leading line of the bridge.</td>', 'I like this shot, but I would have liked it more with the tower on the right cropped out.  Its brightness draws the eye away from the leading line of the bridge.', '2010-04-26 18:59:12.000000', NULL, 1),
(5972412, 872994, 73942, '<td valign="top">beautiful capture, I like how you have two versions of the falls here, well falls and then more like a river, the longer exposure on the water is very pretty and helps the water pop against the black creating a nice contrast</td>', 'beautiful capture, I like how you have two versions of the falls here, well falls and then more like a river, the longer exposure on the water is very pretty and helps the water pop against the black creating a nice contrast', '2010-04-26 19:00:30.000000', NULL, 1),
(5972414, 871962, 73942, '<td valign="top">the person totally makes this, I hope pple take the time to see it</td>', 'the person totally makes this, I hope pple take the time to see it', '2010-04-26 19:00:50.000000', NULL, 1),
(5972415, 873058, 73942, '<td valign="top">nice sky and great leading lines</td>', 'nice sky and great leading lines', '2010-04-26 19:01:21.000000', NULL, 1),
(5972417, 874077, 35513, '<td valign="top">Beautiful composition!</td>', 'Beautiful composition!', '2010-04-26 19:01:26.000000', NULL, 1),
(5972419, 874301, 73942, '<td valign="top">not sure how you meant the title, but I see this and read it as, heading home, means rising home to heaven</td>', 'not sure how you meant the title, but I see this and read it as, heading home, means rising home to heaven', '2010-04-26 19:02:09.000000', NULL, 1),
(5972425, 874055, 1024, '<td valign="top">Wonderful, and the perspective just adds to the effect.</td>', 'Wonderful, and the perspective just adds to the effect.', '2010-04-26 19:04:32.000000', NULL, 1),
(5972435, 874031, 1024, '<td valign="top">Just an opinion, but by my definition of a landscape it should not have a person as the center of interest.</td>', 'Just an opinion, but by my definition of a landscape it should not have a person as the center of interest.', '2010-04-26 19:07:07.000000', NULL, 1),
(5972437, 873817, 116489, '<td valign="top">I think the DOF could have been a little deeper, here, but overall I like it!</td>', 'I think the DOF could have been a little deeper, here, but overall I like it!', '2010-04-26 19:10:08.000000', NULL, 1),
(5972438, 873672, 1024, '<td valign="top">I am about halfway through  voting on this challenge, but so far this is my vote for the blue.  Magnificent.</td>', 'I am about halfway through  voting on this challenge, but so far this is my vote for the blue.  Magnificent.', '2010-04-26 19:10:36.000000', NULL, 1),
