(5974725, 872708, 115307, '<td valign="top">There is definitely a blue tint to this image. It wouldn''t be that noticeable except for the fact that all of the other images are completely black and white, so a little bit of color really stands out.</td>', 'There is definitely a blue tint to this image. It wouldn''t be that noticeable except for the fact that all of the other images are completely black and white, so a little bit of color really stands out.', '2010-04-27 16:40:57.000000', NULL, 1),
(5974740, 874205, 10785, '<td valign="top">This is a whimsical look at country life. The repetition of the mailboxes is good here, however the focus is plainly on the mailboxes and not the landscape as a whole. The image is overly grey and somewhat lacking in contrast. Lighting and exposure might have been a problem. Overall it''s a fun image shot with a creative eye.</td>', 'This is a whimsical look at country life. The repetition of the mailboxes is good here, however the focus is plainly on the mailboxes and not the landscape as a whole. The image is overly grey and somewhat lacking in contrast. Lighting and exposure might have been a problem. Overall it''s a fun image shot with a creative eye.', '2010-04-27 16:54:42.000000', NULL, 1),
(5974763, 874024, 113419, '<td valign="top">beautiful</td>', 'beautiful', '2010-04-27 17:16:54.000000', NULL, 1),
(5974765, 874110, 113419, '<td valign="top">this is nice, but I''m bothered by the fact that the hill is topped off</td>', 'this is nice, but I''m bothered by the fact that the hill is topped off', '2010-04-27 17:17:29.000000', NULL, 1),
(5974766, 873814, 113419, '<td valign="top">nice find - great capture</td>', 'nice find - great capture', '2010-04-27 17:17:46.000000', NULL, 1),
(5974768, 874112, 113419, '<td valign="top">just not very interesting</td>', 'just not very interesting', '2010-04-27 17:18:36.000000', NULL, 1),
