(5974778, 873654, 45631, '<td valign="top">I Like the simplicity in this one.</td>', 'I Like the simplicity in this one.', '2010-04-27 17:21:11.000000', NULL, 1),
(5974785, 872305, 45631, '<td valign="top">Nicely shot.  Angled jetties work well here and the boat is position nicely.  Well done.</td>', 'Nicely shot.  Angled jetties work well here and the boat is position nicely.  Well done.', '2010-04-27 17:23:04.000000', NULL, 1),
(5974790, 872532, 45631, '<td valign="top">This image fails to meet the challenge subject for me.</td>', 'This image fails to meet the challenge subject for me.', '2010-04-27 17:25:56.000000', NULL, 1),
(5974793, 873648, 105890, '<td valign="top">very nice landscape but there is so many details, it needs more contrast between forground and background. as the bridge is in the main accent of the composition i would also reduce details in trees becos they are distracting. 7</td>', 'very nice landscape but there is so many details, it needs more contrast between forground and background. as the bridge is in the main accent of the composition i would also reduce details in trees becos they are distracting. 7', '2010-04-27 17:27:19.000000', NULL, 1),
(5974794, 871856, 45631, '<td valign="top">I like this image.  Feel that it may have framed better in portrait orientation and having the top of the buildings in would have completed the picture.  Love the tulips leading me into the shot.</td>', 'I like this image.  Feel that it may have framed better in portrait orientation and having the top of the buildings in would have completed the picture.  Love the tulips leading me into the shot.', '2010-04-27 17:27:34.000000', NULL, 1),
(5974797, 874153, 113419, '<td valign="top">the sky and the water seem to be blown out</td>', 'the sky and the water seem to be blown out', '2010-04-27 17:30:26.000000', NULL, 1),
