(5974801, 873817, 113419, '<td valign="top">very different!  made me stop and look and I like this ALOT!</td>', 'very different!  made me stop and look and I like this ALOT!', '2010-04-27 17:32:55.000000', NULL, 1),
(5974802, 873938, 113419, '<td valign="top">for me this is right on the verge of DNMC</td>', 'for me this is right on the verge of DNMC', '2010-04-27 17:33:47.000000', NULL, 1),
