(5974808, 871750, 113419, '<td valign="top">lovely, very lovely indeed</td>', 'lovely, very lovely indeed', '2010-04-27 17:36:12.000000', NULL, 1),
(5974809, 873622, 113419, '<td valign="top">Nice, very nice!</td>', 'Nice, very nice!', '2010-04-27 17:37:59.000000', NULL, 1),
(5974810, 873234, 113419, '<td valign="top">not digging the green tint</td>', 'not digging the green tint', '2010-04-27 17:38:17.000000', NULL, 1),
(5974811, 873810, 113419, '<td valign="top">this kind of has a 3D feel to it</td>', 'this kind of has a 3D feel to it', '2010-04-27 17:38:42.000000', NULL, 1),
(5974812, 872817, 116499, '<td valign="top">Love the small aperture and how crisp this is. Lots of interesting textures that don''t clash, though the bit of seagrass in the immediate foreground seems a little too bright: tamping it down some would make the house pop even more.</td>', 'Love the small aperture and how crisp this is. Lots of interesting textures that don''t clash, though the bit of seagrass in the immediate foreground seems a little too bright: tamping it down some would make the house pop even more.', '2010-04-27 17:39:43.000000', NULL, 1),
(5974813, 873889, 113419, '<td valign="top">looks like a sketch, especially the sky and trees</td>', 'looks like a sketch, especially the sky and trees', '2010-04-27 17:39:59.000000', NULL, 1),
(5974814, 873806, 113419, '<td valign="top">just a little too soft</td>', 'just a little too soft', '2010-04-27 17:40:49.000000', NULL, 1),
(5974820, 872865, 45631, '<td valign="top">I like this image but it lacks contrast.</td>', 'I like this image but it lacks contrast.', '2010-04-27 17:42:34.000000', NULL, 1),
(5974821, 871850, 113419, '<td valign="top">Good Job!</td>', 'Good Job!', '2010-04-27 17:42:36.000000', NULL, 1),
(5974828, 872532, 76335, '<td valign="top">(9/38) A novel point of view. And I''ve always had a thing for flowers in black and white.</td>', '(9/38) A novel point of view. And I''ve always had a thing for flowers in black and white.', '2010-04-27 17:48:58.000000', NULL, 1),
(5974832, 873242, 76335, '<td valign="top">(10/38) Your title is fitting -- I''m guessing this is California? The tree looks wonderfully out of place, but most impressive against that sky. In black and white, this has an otherworldly feel to it. Really nice.</td>', '(10/38) Your title is fitting -- I''m guessing this is California? The tree looks wonderfully out of place, but most impressive against that sky. In black and white, this has an otherworldly feel to it. Really nice.', '2010-04-27 17:50:31.000000', NULL, 1),
(5974848, 874087, 76335, '<td valign="top">(11/38) It is most serene, though my eye is having trouble finding something to latch on to.</td>', '(11/38) It is most serene, though my eye is having trouble finding something to latch on to.', '2010-04-27 17:56:46.000000', NULL, 1),
(5974852, 871962, 76335, '<td valign="top">(12/38) I guess it''s land, so that makes it a landscape? Great concept -- probably not the best fit for the challenge though.</td>', '(12/38) I guess it''s land, so that makes it a landscape? Great concept -- probably not the best fit for the challenge though.', '2010-04-27 17:57:51.000000', NULL, 1),
(5974855, 872216, 76335, '<td valign="top">(13/38) Beautifully composed -- love the way the sun seems to be rolling along the horizon. Great clouds too.</td>', '(13/38) Beautifully composed -- love the way the sun seems to be rolling along the horizon. Great clouds too.', '2010-04-27 17:59:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5974859, 873433, 76335, '<td valign="top">(14/38) Wonderful feeling of depth, probably enhanced by the lack of color. I feel as though I''m being pulled into the scene.</td>', '(14/38) Wonderful feeling of depth, probably enhanced by the lack of color. I feel as though I''m being pulled into the scene.', '2010-04-27 18:00:47.000000', NULL, 1),
(5974867, 874202, 76335, '<td valign="top">(15/38) Here''s something different. I''m enjoying the ambiguity of this. Is it a traditional landcsape or a cityscape? There are mountains and clouds and lots of land, but then there''s this sprawling metropolis encroaching on the scene. Nicely done.</td>', '(15/38) Here''s something different. I''m enjoying the ambiguity of this. Is it a traditional landcsape or a cityscape? There are mountains and clouds and lots of land, but then there''s this sprawling metropolis encroaching on the scene. Nicely done.', '2010-04-27 18:03:35.000000', NULL, 1),
(5974872, 873951, 76335, '<td valign="top">(16/38) Beautiful. I love the sky especially, the way it balances and completes the composition.</td>', '(16/38) Beautiful. I love the sky especially, the way it balances and completes the composition.', '2010-04-27 18:05:37.000000', NULL, 1),
(5974880, 873736, 61396, '<td valign="top">I like the sense of depth created by the land, creek and clouds. (not voting)</td>', 'I like the sense of depth created by the land, creek and clouds. (not voting)', '2010-04-27 18:07:10.000000', NULL, 1),
(5974886, 873327, 61396, '<td valign="top">Well caught. (not voting)</td>', 'Well caught. (not voting)', '2010-04-27 18:08:08.000000', NULL, 1),
(5974899, 874205, 76335, '<td valign="top">(17/38) Probably more about the mailboxes than the landscape... But then again, maybe not. The boxes work to identify and tell us something about the land behind them. They are placeholders, markers. It''s kind of like looking behind the scenes of the landscape. It''s an unconventional but interesting idea, the more I think about it.</td>', '(17/38) Probably more about the mailboxes than the landscape... But then again, maybe not. The boxes work to identify and tell us something about the land behind them. They are placeholders, markers. It''s kind of like looking behind the scenes of the landscape. It''s an unconventional but interesting idea, the more I think about it.', '2010-04-27 18:14:53.000000', NULL, 1),
(5974900, 873683, 76335, '<td valign="top">(18/38) Jawdroppingly moving and most beautiful. Love this.</td>', '(18/38) Jawdroppingly moving and most beautiful. Love this.', '2010-04-27 18:16:30.000000', NULL, 1),
(5974901, 874293, 61396, '<td valign="top">You can sleep as a baby with such memories. (not voting)</td>', 'You can sleep as a baby with such memories. (not voting)', '2010-04-27 18:16:41.000000', NULL, 1),
(5974902, 873667, 76335, '<td valign="top">(19/38) Fisheye was a great idea for this challenge. I love this, though it feels a bit too sharp in places.</td>', '(19/38) Fisheye was a great idea for this challenge. I love this, though it feels a bit too sharp in places.', '2010-04-27 18:17:23.000000', NULL, 1),
(5974903, 873340, 61396, '<td valign="top">The lighting on the fence, the reflection in the windows and the distant wind mills join together to make this well toned image a keeper. (not voting)</td>', 'The lighting on the fence, the reflection in the windows and the distant wind mills join together to make this well toned image a keeper. (not voting)', '2010-04-27 18:17:59.000000', NULL, 1),
(5974923, 873994, 110090, '<td valign="top">One of my favorites 9</td>', 'One of my favorites 9', '2010-04-27 18:43:05.000000', NULL, 1),
(5974939, 873648, 113419, '<td valign="top">stunning!</td>', 'stunning!', '2010-04-27 18:49:45.000000', NULL, 1),
(5974942, 873857, 113419, '<td valign="top">love it</td>', 'love it', '2010-04-27 18:50:09.000000', NULL, 1),
(5974950, 874049, 113419, '<td valign="top">nice work!</td>', 'nice work!', '2010-04-27 18:53:51.000000', NULL, 1),
(5975064, 874024, 23484, '<td valign="top">I love the way blue sky''s look in B&amp;W. Nice job.</td>', 'I love the way blue sky''s look in B&W. Nice job.', '2010-04-27 20:02:49.000000', NULL, 1),
(5975067, 872625, 23484, '<td valign="top">Great angle and softness. Nice job with that exposure.</td>', 'Great angle and softness. Nice job with that exposure.', '2010-04-27 20:03:55.000000', NULL, 1),
(5975073, 872278, 23484, '<td valign="top">Wellfleet, had dinner there one night. Nice pattern and lighting.</td>', 'Wellfleet, had dinner there one night. Nice pattern and lighting.', '2010-04-27 20:06:22.000000', NULL, 1),
(5975076, 871765, 23484, '<td valign="top">Very cool perspective.</td>', 'Very cool perspective.', '2010-04-27 20:06:55.000000', NULL, 1),
(5975083, 873556, 110023, '<td valign="top">Cute and different! :)</td>', 'Cute and different! :)', '2010-04-27 20:12:48.000000', NULL, 1),
(5975085, 873817, 110023, '<td valign="top">I really like the texture!</td>', 'I really like the texture!', '2010-04-27 20:14:42.000000', NULL, 1),
(5975094, 873242, 36616, '<td valign="top">A good sky, poor ground - very little interest in rows of plants which are all the same height and colour</td>', 'A good sky, poor ground - very little interest in rows of plants which are all the same height and colour', '2010-04-27 20:20:37.000000', NULL, 1),
(5975100, 874167, 36616, '<td valign="top">I do not see any reason to stay and study this pic. Some flowers in an untidy area, a child with what might be a camera - not very clear.</td>', 'I do not see any reason to stay and study this pic. Some flowers in an untidy area, a child with what might be a camera - not very clear.', '2010-04-27 20:25:14.000000', NULL, 1),
(5975106, 874230, 36616, '<td valign="top">difficult to tell with b&amp;w whose grass is greener. foreground and sky good. middle ground weak. immediate focus on sky rather than landscape</td>', 'difficult to tell with b&w whose grass is greener. foreground and sky good. middle ground weak. immediate focus on sky rather than landscape', '2010-04-27 20:27:35.000000', NULL, 1),
(5975116, 874174, 10785, '<td valign="top">The repetition is so very interesting and the disappearing perspective is pretty cool too. It has good shadow but the highlights are very blown out. I don''t suppose it matters much due to the fact that all you need to see is in the central part of the photo. How can this be improved? If there were a way to get that disappearing perspective arranged diagonally ocross the field of view, it would be stronger still compositionally... but I wouldn''t know how to do that.</td>', 'The repetition is so very interesting and the disappearing perspective is pretty cool too. It has good shadow but the highlights are very blown out. I don''t suppose it matters much due to the fact that all you need to see is in the central part of the photo. How can this be improved? If there were a way to get that disappearing perspective arranged diagonally ocross the field of view, it would be stronger still compositionally... but I wouldn''t know how to do that.', '2010-04-27 20:33:29.000000', NULL, 1),
(5975117, 872709, 10785, '<td valign="top">This is a good view for a landscape, sort of on the edge here. It would be good to see the buildings centered in the frame or going across the entire frame. (They kind of end at the right) Also it is somewhat grey overall. The edges looks somewhat fuzzy which might be due to the limitations of the lens.</td>', 'This is a good view for a landscape, sort of on the edge here. It would be good to see the buildings centered in the frame or going across the entire frame. (They kind of end at the right) Also it is somewhat grey overall. The edges looks somewhat fuzzy which might be due to the limitations of the lens.', '2010-04-27 20:36:08.000000', NULL, 1),
(5975120, 874245, 10785, '<td valign="top">Well, this is kind of limited in view for a landscape photo. The back of the bus stop isn''t really that interesting as a subject.</td>', 'Well, this is kind of limited in view for a landscape photo. The back of the bus stop isn''t really that interesting as a subject.', '2010-04-27 20:38:10.000000', NULL, 1),
(5975121, 874172, 79602, '<td valign="top">I love trees, especially when they are isolated like this.  This is a beautiful, high contrast scene.  The faint trace of a fence line is the icing on the cake...  :o)</td>', 'I love trees, especially when they are isolated like this.  This is a beautiful, high contrast scene.  The faint trace of a fence line is the icing on the cake...  :o)', '2010-04-27 20:38:19.000000', NULL, 1),
(5975126, 872198, 79602, '<td valign="top">I''m always amazed that trees can grow out from rocky terrains.  Nice work!</td>', 'I''m always amazed that trees can grow out from rocky terrains.  Nice work!', '2010-04-27 20:39:55.000000', NULL, 1),
(5975127, 872073, 10785, '<td valign="top">Great shadow and light play here.</td>', 'Great shadow and light play here.', '2010-04-27 20:40:22.000000', NULL, 1),
(5975129, 873546, 10785, '<td valign="top">Whimsical light...</td>', 'Whimsical light...', '2010-04-27 20:40:53.000000', NULL, 1),
(5975132, 874084, 79602, '<td valign="top">Very beautiful.  I love the tone used here...</td>', 'Very beautiful.  I love the tone used here...', '2010-04-27 20:42:08.000000', NULL, 1),
(5975135, 874301, 10785, '<td valign="top">Whatever is in the foreground here, it would have been good to get more of it to give the photo more perspective.</td>', 'Whatever is in the foreground here, it would have been good to get more of it to give the photo more perspective.', '2010-04-27 20:42:36.000000', NULL, 1),
(5975139, 872708, 10785, '<td valign="top">I didn''t quite care for the blue toned images I have seen so far but this one is very good because it gives a feeling of coldness and it has good tonal range from dark to light.</td>', 'I didn''t quite care for the blue toned images I have seen so far but this one is very good because it gives a feeling of coldness and it has good tonal range from dark to light.', '2010-04-27 20:44:48.000000', NULL, 1),
(5975144, 872457, 79602, '<td valign="top">You pulled this back lighting off wonderfully.  Beautiful!</td>', 'You pulled this back lighting off wonderfully.  Beautiful!', '2010-04-27 20:47:19.000000', NULL, 1),
(5975148, 874217, 79602, '<td valign="top">I really like the tilt in this.  It allows an average scene to be more than, well, average! ;o)  Great title - love the lines...</td>', 'I really like the tilt in this.  It allows an average scene to be more than, well, average! ;o)  Great title - love the lines...', '2010-04-27 20:48:58.000000', NULL, 1),
(5975151, 873058, 10785, '<td valign="top">The landscape here is a little flat lacking in visual interest. There are too many footprints here making it more chaotic.</td>', 'The landscape here is a little flat lacking in visual interest. There are too many footprints here making it more chaotic.', '2010-04-27 20:50:18.000000', NULL, 1),
(5975153, 874223, 10785, '<td valign="top">A wonerful scene with good shapes showing the slope of the lnd. It is somewhat lacking contrast making the light kind of flat and dull. I think playing with the levels will help bump up the darker and lighter tones.</td>', 'A wonerful scene with good shapes showing the slope of the lnd. It is somewhat lacking contrast making the light kind of flat and dull. I think playing with the levels will help bump up the darker and lighter tones.', '2010-04-27 20:51:40.000000', NULL, 1),
(5975154, 874055, 79602, '<td valign="top">Oh my goodness - what a beautiful capture! The exposure is just right...</td>', 'Oh my goodness - what a beautiful capture! The exposure is just right...', '2010-04-27 20:51:47.000000', NULL, 1),
(5975158, 873844, 79602, '<td valign="top">I love a good fence line.  Nice sky, too!</td>', 'I love a good fence line.  Nice sky, too!', '2010-04-27 20:52:50.000000', NULL, 1),
(5975161, 873743, 10785, '<td valign="top">I think you kind of missed the perspective with this view. The road could really act as a leading line through the shot but you can''t really see it. Only half the image is filled.</td>', 'I think you kind of missed the perspective with this view. The road could really act as a leading line through the shot but you can''t really see it. Only half the image is filled.', '2010-04-27 20:53:12.000000', NULL, 1),
(5975168, 873393, 79602, '<td valign="top">This photo shows a wonderful sense of scale, and I love the exposure used to freeze the water.  Unfortunately, there are dust spots above the house/lodge that detract from the photo.  Everyone gets them!</td>', 'This photo shows a wonderful sense of scale, and I love the exposure used to freeze the water.  Unfortunately, there are dust spots above the house/lodge that detract from the photo.  Everyone gets them!', '2010-04-27 20:56:31.000000', NULL, 1),
(5975171, 872548, 79602, '<td valign="top">I''m not normally a fan of city scenes rendered in B&amp;W, but this is just gorgeous.  Wonderful conversion!</td>', 'I''m not normally a fan of city scenes rendered in B&W, but this is just gorgeous.  Wonderful conversion!', '2010-04-27 20:58:24.000000', NULL, 1),
(5975178, 872278, 79602, '<td valign="top">I''m sure some may not like the abstract nature of this sandscape (and that''s too bad), but I LOVE it!  The shadows, light, texture and tones are just wonderful.  Sometimes, simple is better. This would look beautiful framed and hanging.  A 10 from me...<br/> <br/>:o)</td>', 'I''m sure some may not like the abstract nature of this sandscape (and that''s too bad), but I LOVE it!  The shadows, light, texture and tones are just wonderful.  Sometimes, simple is better. This would look beautiful framed and hanging.  A 10 from me... :o)', '2010-04-27 21:02:23.000000', NULL, 1),
(5975180, 872836, 79602, '<td valign="top">This is delightfully moody...</td>', 'This is delightfully moody...', '2010-04-27 21:03:06.000000', NULL, 1),
(5975186, 874106, 79602, '<td valign="top">I love a good, country road...   This is a nice scene, but a bit more contrast might have helped it to look a little less flat.</td>', 'I love a good, country road...   This is a nice scene, but a bit more contrast might have helped it to look a little less flat.', '2010-04-27 21:06:55.000000', NULL, 1),
(5975200, 873835, 79602, '<td valign="top">I love the light and shadows, but I feel the B&amp;W conversion has detracted from the sky...</td>', 'I love the light and shadows, but I feel the B&W conversion has detracted from the sky...', '2010-04-27 21:13:29.000000', NULL, 1),
(5975201, 872089, 76335, '<td valign="top">(20/38) I love the point of view but the textures feel very flat -- sky especially. Also, the contrast isn''t what it could be. Maybe experiment with different channels?</td>', '(20/38) I love the point of view but the textures feel very flat -- sky especially. Also, the contrast isn''t what it could be. Maybe experiment with different channels?', '2010-04-27 21:15:39.000000', NULL, 1),
(5975203, 874127, 76335, '<td valign="top">(21/38) Beautiful and full of energy. I''m guessing the shadow is from the moon?</td>', '(21/38) Beautiful and full of energy. I''m guessing the shadow is from the moon?', '2010-04-27 21:16:51.000000', NULL, 1),
