(5975209, 873987, 79602, '<td valign="top">I love this minimalistic capture.  I think this might have been a little stronger with the trees off center, but that is a matter of personal preference and certainly doesn''t detract from this image.  Beautiful, low key conversion!</td>', 'I love this minimalistic capture.  I think this might have been a little stronger with the trees off center, but that is a matter of personal preference and certainly doesn''t detract from this image.  Beautiful, low key conversion!', '2010-04-27 21:20:43.000000', NULL, 1),
(5975212, 873328, 66635, '<td valign="top">Oh how wonderful!</td>', 'Oh how wonderful!', '2010-04-27 21:22:07.000000', NULL, 1),
(5975214, 873625, 79602, '<td valign="top">What a beautiful vantage point!  I love the reflection and the darker foreground vs. the lighter city background.  Nice work!</td>', 'What a beautiful vantage point!  I love the reflection and the darker foreground vs. the lighter city background.  Nice work!', '2010-04-27 21:22:41.000000', NULL, 1),
