(5976851, 874083, 7786, '<td valign="top">The subject and composition is good but the image is lacking all details and sharpness. Learn to use Unsharp Mask for better image sharpness.</td>', 'The subject and composition is good but the image is lacking all details and sharpness. Learn to use Unsharp Mask for better image sharpness.', '2010-04-28 10:09:11.000000', NULL, 1),
(5976991, 873877, 102195, '<td valign="top">excellent graphic design!</td>', 'excellent graphic design!', '2010-04-28 11:06:37.000000', NULL, 1),
(5976995, 872179, 102195, '<td valign="top">gorgeous!</td>', 'gorgeous!', '2010-04-28 11:06:54.000000', NULL, 1),
(5977000, 873328, 7786, '<td valign="top">Flott mynd. Mt. Kevin er að gera góða hluti í þessari keppni.</td>', 'Flott mynd. Mt. Kevin er að gera góða hluti í þessari keppni.', '2010-04-28 11:08:00.000000', NULL, 1),
(5977011, 873654, 116241, '<td valign="top">I''d like this better if the horizon did not go right through the middle.</td>', 'I''d like this better if the horizon did not go right through the middle.', '2010-04-28 11:12:31.000000', NULL, 1),
(5977012, 873790, 116241, '<td valign="top">Wonderful angle.  Contrast lovely.</td>', 'Wonderful angle.  Contrast lovely.', '2010-04-28 11:13:31.000000', NULL, 1),
(5977016, 873013, 69368, '<td valign="top">could be a very nice one if the big tree in foreground wouldn''t distrackting so much</td>', 'could be a very nice one if the big tree in foreground wouldn''t distrackting so much', '2010-04-28 11:15:49.000000', NULL, 1),
(5977017, 874049, 116241, '<td valign="top">Love the creative angle.</td>', 'Love the creative angle.', '2010-04-28 11:16:44.000000', NULL, 1),
(5977022, 872532, 116241, '<td valign="top">The way the light catches the tulip is lovely.</td>', 'The way the light catches the tulip is lovely.', '2010-04-28 11:18:09.000000', NULL, 1),
(5977026, 873358, 116241, '<td valign="top">What a busy image.</td>', 'What a busy image.', '2010-04-28 11:19:54.000000', NULL, 1),
(5977027, 873710, 116241, '<td valign="top">Simple and powerful.</td>', 'Simple and powerful.', '2010-04-28 11:20:20.000000', NULL, 1),
(5977043, 872811, 116241, '<td valign="top">WOW!  What a powerful image.  Great contrast, great composition.  My eye travels with the man right into the image.</td>', 'WOW!  What a powerful image.  Great contrast, great composition.  My eye travels with the man right into the image.', '2010-04-28 11:27:26.000000', NULL, 1),
(5977051, 873877, 116241, '<td valign="top">Simplicity!!!!!</td>', 'Simplicity!!!!!', '2010-04-28 11:31:44.000000', NULL, 1),
(5977061, 872858, 116241, '<td valign="top">Beautiful, haunting landscape.  Great composition horizontally - rule of thirds prevails.</td>', 'Beautiful, haunting landscape.  Great composition horizontally - rule of thirds prevails.', '2010-04-28 11:35:28.000000', NULL, 1),
(5977064, 874106, 116241, '<td valign="top">Could be more powerful with more contrast.</td>', 'Could be more powerful with more contrast.', '2010-04-28 11:36:11.000000', NULL, 1),
(5977086, 872179, 116241, '<td valign="top">The balance of this photo is great.  And the contrast of textures makes it more calming.</td>', 'The balance of this photo is great.  And the contrast of textures makes it more calming.', '2010-04-28 11:45:26.000000', NULL, 1),
(5977088, 873888, 116241, '<td valign="top">Lucky to be able to get this subject.  Most of us can''t.  I love it.</td>', 'Lucky to be able to get this subject.  Most of us can''t.  I love it.', '2010-04-28 11:46:01.000000', NULL, 1),
(5977090, 872709, 116241, '<td valign="top">I wish it were more in focus.</td>', 'I wish it were more in focus.', '2010-04-28 11:47:05.000000', NULL, 1),
(5977092, 872523, 116241, '<td valign="top">The simplicity of the subject is amazing.  The composition makes the photo.</td>', 'The simplicity of the subject is amazing.  The composition makes the photo.', '2010-04-28 11:48:39.000000', NULL, 1),
(5977101, 873994, 116241, '<td valign="top">Wonderful contrast of blacks and whites, great composition.</td>', 'Wonderful contrast of blacks and whites, great composition.', '2010-04-28 11:51:56.000000', NULL, 1),
(5977104, 873879, 116241, '<td valign="top">Great shot.  A little gray</td>', 'Great shot.  A little gray', '2010-04-28 11:52:37.000000', NULL, 1),
(5977107, 872555, 116241, '<td valign="top">Great light, great contrast, great perspective.</td>', 'Great light, great contrast, great perspective.', '2010-04-28 11:54:33.000000', NULL, 1),
(5977170, 871817, 116489, '<td valign="top">I would have liked this shot more if you had rotated it slightly to make the shoreline horizontal.</td>', 'I would have liked this shot more if you had rotated it slightly to make the shoreline horizontal.', '2010-04-28 12:18:02.000000', NULL, 1),
(5977173, 874112, 116489, '<td valign="top">I would have liked to see more contrast between the grain and the fields in this one.</td>', 'I would have liked to see more contrast between the grain and the fields in this one.', '2010-04-28 12:18:45.000000', NULL, 1),
(5977179, 874165, 115498, '<td valign="top">worthless shitty graffiti</td>', 'worthless shitty graffiti', '2010-04-28 12:21:32.000000', NULL, 1),
(5977189, 873433, 35545, '<td valign="top">This really has the feel of the wide open road.</td>', 'This really has the feel of the wide open road.', '2010-04-28 12:25:51.000000', NULL, 1),
(5977311, 873231, 23484, '<td valign="top">Beautiful well composed city shot. Love the perspective from above.</td>', 'Beautiful well composed city shot. Love the perspective from above.', '2010-04-28 13:56:41.000000', NULL, 1),
(5977315, 872811, 23484, '<td valign="top">Love the long exposure. ND10?</td>', 'Love the long exposure. ND10?', '2010-04-28 13:57:51.000000', NULL, 1),
(5977316, 874217, 23484, '<td valign="top">Cool angle on this. I like it.</td>', 'Cool angle on this. I like it.', '2010-04-28 13:58:07.000000', NULL, 1),
(5977317, 873448, 23484, '<td valign="top">Fantastic shot. 9</td>', 'Fantastic shot. 9', '2010-04-28 13:58:21.000000', NULL, 1),
(5977320, 873759, 23484, '<td valign="top">Beautiful image. Love the effect of the log in the water.</td>', 'Beautiful image. Love the effect of the log in the water.', '2010-04-28 14:02:09.000000', NULL, 1),
(5977325, 873671, 7786, '<td valign="top">Beautiful scenery. That airplane ruins the whole thing IMO. Without it, the image would score much higher.</td>', 'Beautiful scenery. That airplane ruins the whole thing IMO. Without it, the image would score much higher.', '2010-04-28 14:08:12.000000', NULL, 1),
(5977369, 873656, 67258, '<td valign="top">Beautiful, serene, peaceful.</td>', 'Beautiful, serene, peaceful.', '2010-04-28 14:36:02.000000', NULL, 1),
(5977391, 874044, 116439, '<td valign="top">The sunny areas seem overlit</td>', 'The sunny areas seem overlit', '2010-04-28 14:51:30.000000', NULL, 1),
(5977393, 873608, 116439, '<td valign="top">Would prefer more texture in the water; the rocks came out beautifully.</td>', 'Would prefer more texture in the water; the rocks came out beautifully.', '2010-04-28 14:51:46.000000', NULL, 1),
(5977394, 874083, 116439, '<td valign="top">The trees in the background came out grainy after the b/w process.</td>', 'The trees in the background came out grainy after the b/w process.', '2010-04-28 14:52:11.000000', NULL, 1),
(5977395, 870853, 116439, '<td valign="top">I''d prefer this photo if it were less busy; it''s also a bit difficult to discern the contours of the land in the foreground.</td>', 'I''d prefer this photo if it were less busy; it''s also a bit difficult to discern the contours of the land in the foreground.', '2010-04-28 14:52:57.000000', NULL, 1),
(5977397, 872532, 116439, '<td valign="top">Nice lighting; I like the shot a lot but</td>', 'Nice lighting; I like the shot a lot but', '2010-04-28 14:53:59.000000', NULL, 1),
(5977398, 873710, 116439, '<td valign="top">Striking visual effect.  Would it suffer from slightly lightening the foreground to show texture?</td>', 'Striking visual effect.  Would it suffer from slightly lightening the foreground to show texture?', '2010-04-28 14:55:20.000000', NULL, 1),
(5977400, 873461, 116439, '<td valign="top">The water is so perfect, but it''s wildly overexposed on top, like the trees have their hair on fire :)</td>', 'The water is so perfect, but it''s wildly overexposed on top, like the trees have their hair on fire :)', '2010-04-28 14:57:16.000000', NULL, 1),
(5977401, 873805, 116439, '<td valign="top">Somehow, the color process makes this look flat, even though the depth is clearly shown by the trees.  Darkening the center would probably help.</td>', 'Somehow, the color process makes this look flat, even though the depth is clearly shown by the trees.  Darkening the center would probably help.', '2010-04-28 14:57:50.000000', NULL, 1),
(5977403, 872599, 116439, '<td valign="top">Like the starkness of the bridge; wish you''d cropped the trees on the right out to play it up.</td>', 'Like the starkness of the bridge; wish you''d cropped the trees on the right out to play it up.', '2010-04-28 14:58:14.000000', NULL, 1),
(5977406, 873213, 116439, '<td valign="top">Too much going on -- where do you want me to look?</td>', 'Too much going on -- where do you want me to look?', '2010-04-28 14:59:09.000000', NULL, 1),
(5977416, 874218, 116439, '<td valign="top">This is a really great idea that I think might be better executed in detailed shots than in this landscape format.</td>', 'This is a really great idea that I think might be better executed in detailed shots than in this landscape format.', '2010-04-28 15:04:17.000000', NULL, 1),
(5977419, 873093, 116439, '<td valign="top">Perspective makes this photo look like it was compressed wrong; a higher shot with less of the water in the foreground would have worked better</td>', 'Perspective makes this photo look like it was compressed wrong; a higher shot with less of the water in the foreground would have worked better', '2010-04-28 15:05:56.000000', NULL, 1),
(5977420, 874110, 116439, '<td valign="top">Wish you''d cropped off the house in the top left corner, which distracts from the beauty of the waterfall, especially because it emphasizes the photographer''s perspective</td>', 'Wish you''d cropped off the house in the top left corner, which distracts from the beauty of the waterfall, especially because it emphasizes the photographer''s perspective', '2010-04-28 15:06:47.000000', NULL, 1),
(5977426, 874112, 116439, '<td valign="top">Grainy foreground is too bad; nice concept</td>', 'Grainy foreground is too bad; nice concept', '2010-04-28 15:07:25.000000', NULL, 1),
(5977428, 873234, 116439, '<td valign="top">Green?  Color process issue?</td>', 'Green?  Color process issue?', '2010-04-28 15:08:01.000000', NULL, 1),
(5977434, 874167, 116439, '<td valign="top">I love this idea *so much!*  The composition is nice; the eye is drawn right to the camer and the kid''s shirt because they''re so dark, and the evenness of the posts in contrast with the riot of flowers makes for a great visual device.</td>', 'I love this idea *so much!*  The composition is nice; the eye is drawn right to the camer and the kid''s shirt because they''re so dark, and the evenness of the posts in contrast with the riot of flowers makes for a great visual device.', '2010-04-28 15:09:49.000000', NULL, 1),
(5977437, 874041, 116439, '<td valign="top">the cemetary is a little visually confusing to me; if you cropped the whole thing right in the middle and took the left side, you''d miss some good cloud action but maybe get a clearer visual focus.</td>', 'the cemetary is a little visually confusing to me; if you cropped the whole thing right in the middle and took the left side, you''d miss some good cloud action but maybe get a clearer visual focus.', '2010-04-28 15:11:14.000000', NULL, 1),
(5977439, 872252, 113412, '<td valign="top">hgghtrtyfghrtyd</td>', 'hgghtrtyfghrtyd', '2010-04-28 15:11:44.000000', NULL, 1),
(5977440, 871102, 116439, '<td valign="top">heeeeeeelp, the world is falling to the left!</td>', 'heeeeeeelp, the world is falling to the left!', '2010-04-28 15:12:12.000000', NULL, 1),
(5977445, 873870, 116439, '<td valign="top">You know what would make the world a better place?  BANNING ANTENNAS.  Not your fault, but tricky!</td>', 'You know what would make the world a better place?  BANNING ANTENNAS.  Not your fault, but tricky!', '2010-04-28 15:13:19.000000', NULL, 1),
(5977448, 874223, 116439, '<td valign="top">Tricky to make this photo look right -- the way the road cuts across makes things look tipped to the left side, but if you straightened that, the buildings might look un-square...</td>', 'Tricky to make this photo look right -- the way the road cuts across makes things look tipped to the left side, but if you straightened that, the buildings might look un-square...', '2010-04-28 15:14:09.000000', NULL, 1),
(5977449, 874217, 116439, '<td valign="top">Bonus points for originality.</td>', 'Bonus points for originality.', '2010-04-28 15:14:34.000000', NULL, 1),
(5977461, 873647, 116439, '<td valign="top">Oh, top right corner!  How I wish you were lighter!  Cropping an inch off might be your best solution.</td>', 'Oh, top right corner!  How I wish you were lighter!  Cropping an inch off might be your best solution.', '2010-04-28 15:17:43.000000', NULL, 1),
(5977468, 874262, 116439, '<td valign="top">Haze obscures the foreground more than would be optimally awesome.</td>', 'Haze obscures the foreground more than would be optimally awesome.', '2010-04-28 15:18:58.000000', NULL, 1),
(5977492, 873358, 61396, '<td valign="top">You got the structure and tones for Escher to use this as a model for some of his works. (not voting)</td>', 'You got the structure and tones for Escher to use this as a model for some of his works. (not voting)', '2010-04-28 15:31:10.000000', NULL, 1),
(5977674, 872802, 103310, '<td valign="top">Magnifying glass scoop in picture. Splendid reflection. the black part Right of the photograph asks too much attention.</td>', 'Magnifying glass scoop in picture. Splendid reflection. the black part Right of the photograph asks too much attention.', '2010-04-28 16:52:10.000000', NULL, 1),
(5977676, 874055, 62357, '<td valign="top">Just coming back doing some score adjustments (in your case up!).  The tonal range in this image is spot on.  You have done a really good conversion.  The image itself is spot on too.  Well done.</td>', 'Just coming back doing some score adjustments (in your case up!).  The tonal range in this image is spot on.  You have done a really good conversion.  The image itself is spot on too.  Well done.', '2010-04-28 16:53:34.000000', NULL, 1),
(5977677, 874077, 62357, '<td valign="top">I''m a sucker for reflections and vanishing points.  This is lovely.</td>', 'I''m a sucker for reflections and vanishing points.  This is lovely.', '2010-04-28 16:54:08.000000', NULL, 1),
(5977680, 871856, 62357, '<td valign="top">Yep, liking this very much.  I miss Chicago.</td>', 'Yep, liking this very much.  I miss Chicago.', '2010-04-28 16:54:53.000000', NULL, 1),
(5977683, 871750, 62357, '<td valign="top">very simple and effective.</td>', 'very simple and effective.', '2010-04-28 16:55:14.000000', NULL, 1),
(5977685, 872457, 62357, '<td valign="top">The backlighting is really well done and extremely effective.  Excellent.</td>', 'The backlighting is really well done and extremely effective.  Excellent.', '2010-04-28 16:55:52.000000', NULL, 1),
(5977688, 872305, 62357, '<td valign="top">Gorgeous tranquil scene.  I like the slight toning to this.</td>', 'Gorgeous tranquil scene.  I like the slight toning to this.', '2010-04-28 16:56:27.000000', NULL, 1),
(5977693, 873389, 62357, '<td valign="top">Rather interesting landscape.  I like the inclusion of the debris - makes it a bit different.</td>', 'Rather interesting landscape.  I like the inclusion of the debris - makes it a bit different.', '2010-04-28 17:00:19.000000', NULL, 1),
(5977698, 872022, 62357, '<td valign="top">This is very lovely. Fabulous sky</td>', 'This is very lovely. Fabulous sky', '2010-04-28 17:01:30.000000', NULL, 1),
(5977704, 874027, 62357, '<td valign="top">Lovely image.</td>', 'Lovely image.', '2010-04-28 17:03:27.000000', NULL, 1),
(5977705, 874190, 62357, '<td valign="top">the reflections are wonderful</td>', 'the reflections are wonderful', '2010-04-28 17:03:49.000000', NULL, 1),
(5977712, 871962, 62357, '<td valign="top">Quirky.  I like it</td>', 'Quirky.  I like it', '2010-04-28 17:08:23.000000', NULL, 1),
(5977714, 872597, 62357, '<td valign="top">Even though the darks are very dark, I do like this a lot.  I would perhaps prefer the foreground to be a tiny bit brighter, but overall I love this.</td>', 'Even though the darks are very dark, I do like this a lot.  I would perhaps prefer the foreground to be a tiny bit brighter, but overall I love this.', '2010-04-28 17:09:27.000000', NULL, 1),
(5977717, 874245, 62357, '<td valign="top">certainly a non-traditional approach in this challenge.  I like it very much.  I already voted, so just commenting right now.</td>', 'certainly a non-traditional approach in this challenge.  I like it very much.  I already voted, so just commenting right now.', '2010-04-28 17:10:34.000000', NULL, 1),
(5977719, 873654, 62357, '<td valign="top">Someone from the low country I guess. I like the grain - it works well.  Composition is really good.</td>', 'Someone from the low country I guess. I like the grain - it works well.  Composition is really good.', '2010-04-28 17:11:26.000000', NULL, 1),
(5977727, 874293, 62357, '<td valign="top">Reminds me of Edward Steichen''s image The Pond, Moonlight, albeit the daylight version. I love tree images but combined with reflections well, definitely works for me.  Only thing I may change with this is to boost the darks in the trees, trouble with that in basic, it would affect the reflections, which are perfect. <br/> <br/> <br/><a href="//www.guardian.co.uk/world/2006/feb/15/usa.arts" rel="nofollow" target="_blank">The Pond</a></td>', 'Reminds me of Edward Steichen''s image The Pond, Moonlight, albeit the daylight version. I love tree images but combined with reflections well, definitely works for me.  Only thing I may change with this is to boost the darks in the trees, trouble with that in basic, it would affect the reflections, which are perfect.   The Pond', '2010-04-28 17:20:01.000000', NULL, 1),
(5977732, 874049, 114219, '<td valign="top">I am not sure if it''s DNMC or not, but definitely a cool photo.....instant fave for me....7 just for the amazing framing you did</td>', 'I am not sure if it''s DNMC or not, but definitely a cool photo.....instant fave for me....7 just for the amazing framing you did', '2010-04-28 17:21:59.000000', NULL, 1),
(5977733, 874024, 114219, '<td valign="top">great photo!  is this in Alberta?</td>', 'great photo!  is this in Alberta?', '2010-04-28 17:22:49.000000', NULL, 1),
(5977807, 873358, 67258, '<td valign="top">This is my stomping ground!  I spend every weekend here,  Good conversion - I haven''t done a b&amp;w of the viaduct, must try one!  You have done really well to not include the bushes and trees that are just out of frame to the bottom right - I haven''t ever managed that!  I really like this.</td>', 'This is my stomping ground!  I spend every weekend here,  Good conversion - I haven''t done a b&w of the viaduct, must try one!  You have done really well to not include the bushes and trees that are just out of frame to the bottom right - I haven''t ever managed that!  I really like this.', '2010-04-28 17:52:49.000000', NULL, 1),
(5977814, 872046, 116241, '<td valign="top">Simple, great contrast.  The eye is lead right into the image.</td>', 'Simple, great contrast.  The eye is lead right into the image.', '2010-04-28 17:57:18.000000', NULL, 1),
(5977910, 872315, 76335, '<td valign="top">(22/38) Beautifully composed in that all you see is rocks and water. I like the dappled light too.</td>', '(22/38) Beautifully composed in that all you see is rocks and water. I like the dappled light too.', '2010-04-28 18:56:35.000000', NULL, 1),
(5977913, 873646, 76335, '<td valign="top">(23/38) I do like the wild lines and shapes that the water is forming. Feels a bit too sharp though.</td>', '(23/38) I do like the wild lines and shapes that the water is forming. Feels a bit too sharp though.', '2010-04-28 18:57:31.000000', NULL, 1),
(5977919, 874199, 76335, '<td valign="top">(24/38) A wonderful sort of pastoral scene. I''m really liking the single light in the top window of the lighthouse.</td>', '(24/38) A wonderful sort of pastoral scene. I''m really liking the single light in the top window of the lighthouse.', '2010-04-28 18:59:07.000000', NULL, 1),
(5977922, 873183, 76335, '<td valign="top">(25/38) Outstanding! This is a cut above the rest, not simply because it''s in black and white, but because it draws its impact from the fact. Beautifully abstract.</td>', '(25/38) Outstanding! This is a cut above the rest, not simply because it''s in black and white, but because it draws its impact from the fact. Beautifully abstract.', '2010-04-28 19:00:59.000000', NULL, 1),
(5977924, 873213, 76335, '<td valign="top">(26/38) Very nicely composed. I wonder if you could have experimented with different black and white channels such that the people didn''t blend in with the background.</td>', '(26/38) Very nicely composed. I wonder if you could have experimented with different black and white channels such that the people didn''t blend in with the background.', '2010-04-28 19:02:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5977927, 873942, 76335, '<td valign="top">(27/38) Very nice. I''m not sure if the barge is a distraction or not. I might like to have seen it not so close to the brige to better balance the composition. Also, the image feels too sharp -- the haloing in the bridge cables, for instance.</td>', '(27/38) Very nice. I''m not sure if the barge is a distraction or not. I might like to have seen it not so close to the brige to better balance the composition. Also, the image feels too sharp -- the haloing in the bridge cables, for instance.', '2010-04-28 19:04:57.000000', NULL, 1),
(5977928, 873502, 76335, '<td valign="top">(28/38) Simple and very effective. I like the soft grain that (I think) I see.</td>', '(28/38) Simple and very effective. I like the soft grain that (I think) I see.', '2010-04-28 19:05:58.000000', NULL, 1),
(5978008, 871829, 10785, '<td valign="top">I like the crop here... Also the wide range of tones make for a lot of texture in the seascape.</td>', 'I like the crop here... Also the wide range of tones make for a lot of texture in the seascape.', '2010-04-28 20:14:57.000000', NULL, 1),
(5978010, 873622, 10785, '<td valign="top">I''s like to see a smaller aperture here.</td>', 'I''s like to see a smaller aperture here.', '2010-04-28 20:16:16.000000', NULL, 1),
(5978019, 874186, 10785, '<td valign="top">The highlights are very blown out here in the left where the sun was shining down. If this was taken in mid afternoon with bright light, try the sunny 16 rule... Use f16 with a shutter speed of 1/iso value. So at iso 100 the shutter would be 1/100.</td>', 'The highlights are very blown out here in the left where the sun was shining down. If this was taken in mid afternoon with bright light, try the sunny 16 rule... Use f16 with a shutter speed of 1/iso value. So at iso 100 the shutter would be 1/100.', '2010-04-28 20:21:13.000000', NULL, 1),
(5978021, 873294, 10785, '<td valign="top">Very simplistic foreground. I love the lines of the timber sticking out of the water. Either it was a very rainy, grey day or this looks somewhat undereposed and lacking contrast.</td>', 'Very simplistic foreground. I love the lines of the timber sticking out of the water. Either it was a very rainy, grey day or this looks somewhat undereposed and lacking contrast.', '2010-04-28 20:22:46.000000', NULL, 1),
(5978030, 873628, 10785, '<td valign="top">Someone''s gunning for a posthumous ribbon! Because I had to use the dictionary, you get the Alternative Blue... because this is like the grunge rock of the challenge. And once it catches on, eveyone will want to be like it and you will move on to more clasical photography because you are ahead of the times!</td>', 'Someone''s gunning for a posthumous ribbon! Because I had to use the dictionary, you get the Alternative Blue... because this is like the grunge rock of the challenge. And once it catches on, eveyone will want to be like it and you will move on to more clasical photography because you are ahead of the times!', '2010-04-28 20:32:18.000000', NULL, 1),
(5978032, 872186, 10785, '<td valign="top">A good black and white landscape with great luminosity and tonal range. Everything is pretty centered though and there is no real interesting compositional elements except for the reflections.</td>', 'A good black and white landscape with great luminosity and tonal range. Everything is pretty centered though and there is no real interesting compositional elements except for the reflections.', '2010-04-28 20:33:33.000000', NULL, 1),
(5978037, 872244, 10785, '<td valign="top">The powerlines kill it for me.</td>', 'The powerlines kill it for me.', '2010-04-28 20:38:09.000000', NULL, 1),
(5978044, 874167, 10785, '<td valign="top">Whimsical shot with the wide open aperture allowing the focus to fade in the distance. I like that it is not oversharpened. The lines of the vine fencing creates a nice rhythm. The peeping photographer adds visual interest.</td>', 'Whimsical shot with the wide open aperture allowing the focus to fade in the distance. I like that it is not oversharpened. The lines of the vine fencing creates a nice rhythm. The peeping photographer adds visual interest.', '2010-04-28 20:42:51.000000', NULL, 1),
(5978047, 873858, 10785, '<td valign="top">That fence leads you right through this photo in both dimensions... horizontal/vertical and through the depth from foreground to background right into the barn. The dotted field flowers on the hill serve to add great textures.</td>', 'That fence leads you right through this photo in both dimensions... horizontal/vertical and through the depth from foreground to background right into the barn. The dotted field flowers on the hill serve to add great textures.', '2010-04-28 20:43:10.000000', NULL, 1),
(5978048, 872576, 10785, '<td valign="top">I think you have used this tree a few times before haven''t you??</td>', 'I think you have used this tree a few times before haven''t you??', '2010-04-28 20:43:16.000000', NULL, 1),
(5978050, 873886, 10785, '<td valign="top">Very strong lines and shapes with the clouds and mountain slopes. Excellent range of tones from highlights and shadows.</td>', 'Very strong lines and shapes with the clouds and mountain slopes. Excellent range of tones from highlights and shadows.', '2010-04-28 20:44:11.000000', NULL, 1),
(5978053, 872945, 10785, '<td valign="top">The overexposed shot doesn''t really hurt this scene and gives it a high key or possibly infra red treatment. The rolling lines of the slopes throughout add good composition and the silhouetted cows add interest.</td>', 'The overexposed shot doesn''t really hurt this scene and gives it a high key or possibly infra red treatment. The rolling lines of the slopes throughout add good composition and the silhouetted cows add interest.', '2010-04-28 20:45:47.000000', NULL, 1),
(5978055, 874284, 10785, '<td valign="top">It doesn''t get much better than this for a landscape. Here you have great composition and shapes forming the scape of the land. You have the curve in the foreground, the mountians forming a v shape in the midground and the excellent sky in the background. With all the awesome photos in this competition, this stands out as at least an honorable mention!</td>', 'It doesn''t get much better than this for a landscape. Here you have great composition and shapes forming the scape of the land. You have the curve in the foreground, the mountians forming a v shape in the midground and the excellent sky in the background. With all the awesome photos in this competition, this stands out as at least an honorable mention!', '2010-04-28 20:46:31.000000', NULL, 1),
(5978056, 874156, 10785, '<td valign="top">Ordered Chaos! A very god compositional technique applied here using the chaos of the blur caused by camera movement yet showing the order of the forest by the vertical lines of the trees.</td>', 'Ordered Chaos! A very god compositional technique applied here using the chaos of the blur caused by camera movement yet showing the order of the forest by the vertical lines of the trees.', '2010-04-28 20:46:59.000000', NULL, 1),
