(5980383, 872046, 114285, '<td valign="top">Top 10, well done.</td>', 'Top 10, well done.', '2010-04-30 01:31:30.000000', NULL, 1),
(5980385, 872441, 114285, '<td valign="top">I like the processing of this photo, it''s very quaint.</td>', 'I like the processing of this photo, it''s very quaint.', '2010-04-30 01:31:59.000000', NULL, 1),
(5980386, 874108, 94235, '<td valign="top">Lovely scene and well exposed for the harsh lighting conditions.</td>', 'Lovely scene and well exposed for the harsh lighting conditions.', '2010-04-30 01:34:40.000000', NULL, 1),
(5980387, 874084, 94235, '<td valign="top">Nice tones. Looks like a painting.</td>', 'Nice tones. Looks like a painting.', '2010-04-30 01:35:13.000000', NULL, 1),
(5980391, 874199, 94235, '<td valign="top">Looks very bleak. Maybe my eyesight but the lighthouse looks a little OOF to me. Nice capture all the same.</td>', 'Looks very bleak. Maybe my eyesight but the lighthouse looks a little OOF to me. Nice capture all the same.', '2010-04-30 01:38:05.000000', NULL, 1),
(5980392, 873478, 94235, '<td valign="top">Nice texture. Simple and very effective.</td>', 'Nice texture. Simple and very effective.', '2010-04-30 01:38:08.000000', NULL, 1),
(5980393, 874289, 114285, '<td valign="top">Crisp, I like it.</td>', 'Crisp, I like it.', '2010-04-30 01:38:21.000000', NULL, 1),
(5980395, 872964, 114285, '<td valign="top">Serenity. 8</td>', 'Serenity. 8', '2010-04-30 01:38:57.000000', NULL, 1),
(5980396, 872854, 114285, '<td valign="top">Ohh I love this one, especially the rolling clouds.</td>', 'Ohh I love this one, especially the rolling clouds.', '2010-04-30 01:39:29.000000', NULL, 1),
(5980397, 874228, 114285, '<td valign="top">Great pic, but can''t really see how it fits the challenge.</td>', 'Great pic, but can''t really see how it fits the challenge.', '2010-04-30 01:40:14.000000', NULL, 1),
(5980398, 872656, 94235, '<td valign="top">Looks a little flat. Maybe a tighter crop excluding the two buildings on the right and less top and bottom, to highlight and give more impact to the white building in the middle. Good shot all the same.</td>', 'Looks a little flat. Maybe a tighter crop excluding the two buildings on the right and less top and bottom, to highlight and give more impact to the white building in the middle. Good shot all the same.', '2010-04-30 01:40:29.000000', NULL, 1),
(5980399, 873022, 114285, '<td valign="top">COOL&gt;:)</td>', 'COOL>:)', '2010-04-30 01:40:41.000000', NULL, 1),
(5980400, 872020, 114285, '<td valign="top">Great perspective. 9</td>', 'Great perspective. 9', '2010-04-30 01:41:21.000000', NULL, 1),
(5980402, 873834, 114285, '<td valign="top">This is gorgeous. 9</td>', 'This is gorgeous. 9', '2010-04-30 01:42:02.000000', NULL, 1),
(5980404, 873879, 114285, '<td valign="top">Hey, good pic, hopefully there was not much damage.</td>', 'Hey, good pic, hopefully there was not much damage.', '2010-04-30 01:43:49.000000', NULL, 1),
(5980405, 874221, 94235, '<td valign="top">Cool scene, well captured.</td>', 'Cool scene, well captured.', '2010-04-30 01:46:04.000000', NULL, 1),
(5980410, 874262, 94235, '<td valign="top">Nicely captured although a little too much negative space at the top IMO. A tighter crop there might have given a more panoramic feel. Good shot all the same.</td>', 'Nicely captured although a little too much negative space at the top IMO. A tighter crop there might have given a more panoramic feel. Good shot all the same.', '2010-04-30 01:47:58.000000', NULL, 1),
(5980412, 872550, 94235, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2010-04-30 01:48:35.000000', NULL, 1),
(5980414, 870795, 94235, '<td valign="top">A little dark and really had to look for the cars to get an idea of the scale of the crane. Very impressive though.</td>', 'A little dark and really had to look for the cars to get an idea of the scale of the crane. Very impressive though.', '2010-04-30 01:50:28.000000', NULL, 1),
(5980415, 874127, 94235, '<td valign="top">Good effect and well taken. The frame finishes it off nicely.</td>', 'Good effect and well taken. The frame finishes it off nicely.', '2010-04-30 01:51:07.000000', NULL, 1),
(5980417, 871750, 94235, '<td valign="top">Great shot. Simple and stunning. Well done.</td>', 'Great shot. Simple and stunning. Well done.', '2010-04-30 01:51:52.000000', NULL, 1),
(5980422, 872073, 94235, '<td valign="top">A great effect with the trees on the right. The sunlit area detracts, a little, for me but still a nice shot.</td>', 'A great effect with the trees on the right. The sunlit area detracts, a little, for me but still a nice shot.', '2010-04-30 01:53:23.000000', NULL, 1),
(5980424, 874048, 94235, '<td valign="top">Nice take. The diffent thickness in your border lines is a little distracting though.</td>', 'Nice take. The diffent thickness in your border lines is a little distracting though.', '2010-04-30 01:54:29.000000', NULL, 1),
(5980425, 873344, 94235, '<td valign="top">Nice panorama. Well captured.</td>', 'Nice panorama. Well captured.', '2010-04-30 01:54:58.000000', NULL, 1),
(5980427, 873800, 94235, '<td valign="top">Well taken. Nice depth.</td>', 'Well taken. Nice depth.', '2010-04-30 01:55:35.000000', NULL, 1),
(5980430, 873888, 94235, '<td valign="top">Wow. You are so lucky to live where you do. Great job of capturing the scene so well.</td>', 'Wow. You are so lucky to live where you do. Great job of capturing the scene so well.', '2010-04-30 01:57:43.000000', NULL, 1),
(5980432, 872653, 94235, '<td valign="top">Lovely reflection. Well framed.</td>', 'Lovely reflection. Well framed.', '2010-04-30 01:58:11.000000', NULL, 1),
(5980433, 873033, 42013, '<td valign="top">I think this qualifies as having a z-axis. Nicely composed!</td>', 'I think this qualifies as having a z-axis. Nicely composed!', '2010-04-30 01:59:11.000000', NULL, 1),
(5980434, 874217, 94235, '<td valign="top">Well taken. Would have been just as good without the tilt.</td>', 'Well taken. Would have been just as good without the tilt.', '2010-04-30 01:59:21.000000', NULL, 1),
(5980436, 874254, 94235, '<td valign="top">Nice exposure. Love the varying tones in the rocks.</td>', 'Nice exposure. Love the varying tones in the rocks.', '2010-04-30 02:00:22.000000', NULL, 1),
(5980474, 873766, 52765, '<td valign="top">I think this is boston</td>', 'I think this is boston', '2010-04-30 02:41:06.000000', NULL, 1),
(5980518, 872332, 37858, '<td valign="top">I like the roots and the range of tones throughout the image.</td>', 'I like the roots and the range of tones throughout the image.', '2010-04-30 03:06:22.000000', NULL, 1),
(5980519, 872315, 37858, '<td valign="top">Good use of light on the cliffs.</td>', 'Good use of light on the cliffs.', '2010-04-30 03:06:43.000000', NULL, 1),
(5980520, 873672, 37858, '<td valign="top">What a clear panorama.  I''d like to spend a week there...but probably not until the wine is harvested.  Well done.</td>', 'What a clear panorama.  I''d like to spend a week there...but probably not until the wine is harvested.  Well done.', '2010-04-30 03:07:36.000000', NULL, 1),
(5980521, 872252, 37858, '<td valign="top">Seems just a tad dark in the trees along the shoreline.  Otherwise I like the range of tones.</td>', 'Seems just a tad dark in the trees along the shoreline.  Otherwise I like the range of tones.', '2010-04-30 03:08:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5980523, 873344, 37858, '<td valign="top">Focus seems a bit off...unless it''s my eyes.</td>', 'Focus seems a bit off...unless it''s my eyes.', '2010-04-30 03:08:52.000000', NULL, 1),
(5980526, 871102, 37858, '<td valign="top">Seems less about the landscape and more about the vehicle.  Nice range of tones though.</td>', 'Seems less about the landscape and more about the vehicle.  Nice range of tones though.', '2010-04-30 03:09:52.000000', NULL, 1),
(5980527, 873266, 37858, '<td valign="top">I like the separation of tones in the trees.  The clouds look a little bit pixilated on my monitor.</td>', 'I like the separation of tones in the trees.  The clouds look a little bit pixilated on my monitor.', '2010-04-30 03:10:54.000000', NULL, 1),
(5980528, 872994, 37858, '<td valign="top">Good clarity and range of tones.</td>', 'Good clarity and range of tones.', '2010-04-30 03:11:15.000000', NULL, 1),
(5980529, 874153, 37858, '<td valign="top">Too blown out for my taste in the light areas and not enough detail in the dark areas.</td>', 'Too blown out for my taste in the light areas and not enough detail in the dark areas.', '2010-04-30 03:12:01.000000', NULL, 1),
(5980530, 874154, 37858, '<td valign="top">Nice detail and composition.</td>', 'Nice detail and composition.', '2010-04-30 03:12:38.000000', NULL, 1),
(5980531, 872599, 37858, '<td valign="top">Good range of tones from gray to black but maybe a bit dull without some more light tones.</td>', 'Good range of tones from gray to black but maybe a bit dull without some more light tones.', '2010-04-30 03:14:12.000000', NULL, 1),
(5980532, 874031, 37858, '<td valign="top">Nice range of tones and a good simple composition.  I like it.</td>', 'Nice range of tones and a good simple composition.  I like it.', '2010-04-30 03:14:50.000000', NULL, 1),
(5980533, 873622, 37858, '<td valign="top">Seems a bit busy for me.  My eye doesn''t settle on anything, but roves around the whole image.</td>', 'Seems a bit busy for me.  My eye doesn''t settle on anything, but roves around the whole image.', '2010-04-30 03:15:29.000000', NULL, 1),
(5980534, 873135, 37858, '<td valign="top">Focus seems strong in the foreground but a bit soft at the trees.  Of course it could be that my old eyesight is failing, too.  Nice composition.</td>', 'Focus seems strong in the foreground but a bit soft at the trees.  Of course it could be that my old eyesight is failing, too.  Nice composition.', '2010-04-30 03:16:49.000000', NULL, 1),
(5980537, 873590, 37858, '<td valign="top">You managed to get good clarity for a subject that is pretty busy.  Nice tonal range too.</td>', 'You managed to get good clarity for a subject that is pretty busy.  Nice tonal range too.', '2010-04-30 03:17:37.000000', NULL, 1),
(5980540, 872566, 37858, '<td valign="top">Dude.  I just finished making night photos on magic island.  I wonder if we were out there on the same evening.  If you have access to photoshop you might consider using the "transform" feature to keep the outter buildings from leaning toward the center of the image.  Otherwise, nice shot.</td>', 'Dude.  I just finished making night photos on magic island.  I wonder if we were out there on the same evening.  If you have access to photoshop you might consider using the "transform" feature to keep the outter buildings from leaning toward the center of the image.  Otherwise, nice shot.', '2010-04-30 03:23:06.000000', NULL, 1),
(5980541, 874096, 37858, '<td valign="top">Nice details in the center of this image.  I like the composition too.</td>', 'Nice details in the center of this image.  I like the composition too.', '2010-04-30 03:23:50.000000', NULL, 1),
(5980543, 872088, 37858, '<td valign="top">Nice range of tones.</td>', 'Nice range of tones.', '2010-04-30 03:25:30.000000', NULL, 1),
(5980544, 873723, 37858, '<td valign="top">I like the composition.  Not sure it is really "black" and white, but didn''t vote down because of the tone.</td>', 'I like the composition.  Not sure it is really "black" and white, but didn''t vote down because of the tone.', '2010-04-30 03:27:06.000000', NULL, 1),
(5980545, 873886, 37858, '<td valign="top">Don''t tell me you just walked out the back door of your home and took this photo.  At least tell me you hiked for a day and a half to get here.<br/> <br/>Really a fine shot and spectacular scenery.</td>', 'Don''t tell me you just walked out the back door of your home and took this photo.  At least tell me you hiked for a day and a half to get here. Really a fine shot and spectacular scenery.', '2010-04-30 03:29:26.000000', NULL, 1),
(5980546, 873068, 37858, '<td valign="top">Good range of tones.</td>', 'Good range of tones.', '2010-04-30 03:30:11.000000', NULL, 1),
(5980548, 872437, 37858, '<td valign="top">Beautiful tones and scenery.  Well done.</td>', 'Beautiful tones and scenery.  Well done.', '2010-04-30 03:30:55.000000', NULL, 1),
(5980549, 874230, 37858, '<td valign="top">This seems a bit soft too me.</td>', 'This seems a bit soft too me.', '2010-04-30 03:33:26.000000', NULL, 1),
(5980550, 873183, 37858, '<td valign="top">I''m not sure I would call this "landscape" but I would call it good photography.  Nice image.</td>', 'I''m not sure I would call this "landscape" but I would call it good photography.  Nice image.', '2010-04-30 03:34:29.000000', NULL, 1),
(5980551, 872653, 37858, '<td valign="top">Great clarity and range of tones.</td>', 'Great clarity and range of tones.', '2010-04-30 03:34:51.000000', NULL, 1),
(5980552, 874190, 37858, '<td valign="top">Great range of tones.  I like the composition too...almost surreal.</td>', 'Great range of tones.  I like the composition too...almost surreal.', '2010-04-30 03:35:37.000000', NULL, 1),
(5980553, 874244, 37858, '<td valign="top">Nice setting and composition.  Tones seem a bit muted to me, though.  I like the detail in the building.</td>', 'Nice setting and composition.  Tones seem a bit muted to me, though.  I like the detail in the building.', '2010-04-30 03:36:41.000000', NULL, 1),
(5980554, 873015, 37858, '<td valign="top">This would be more powerful if there was a little brighter light somewhere in the image.  Of course, I wasn''t there so I don''t know if it was possible to increase the contrast and include a brighter spot somewhere within the composition.</td>', 'This would be more powerful if there was a little brighter light somewhere in the image.  Of course, I wasn''t there so I don''t know if it was possible to increase the contrast and include a brighter spot somewhere within the composition.', '2010-04-30 03:38:02.000000', NULL, 1),
(5980555, 874181, 37858, '<td valign="top">Interesting compostion.  Not sure what to make of the halo effect around the dark triangular item towards the right side.</td>', 'Interesting compostion.  Not sure what to make of the halo effect around the dark triangular item towards the right side.', '2010-04-30 03:39:25.000000', NULL, 1),
(5980556, 872514, 37858, '<td valign="top">Nice clarity and subtle use of light.</td>', 'Nice clarity and subtle use of light.', '2010-04-30 03:40:24.000000', NULL, 1),
(5980557, 872811, 37858, '<td valign="top">Interesting lighting in this one.  A very striking image.</td>', 'Interesting lighting in this one.  A very striking image.', '2010-04-30 03:41:14.000000', NULL, 1),
(5980558, 871676, 37858, '<td valign="top">Interesting landscape.  Good detail for so dark a setting.</td>', 'Interesting landscape.  Good detail for so dark a setting.', '2010-04-30 03:42:16.000000', NULL, 1),
(5980559, 873280, 37858, '<td valign="top">This has "nice composition" written all over it.  The frame/border seems a bit heavy for so clean an image IMHO.</td>', 'This has "nice composition" written all over it.  The frame/border seems a bit heavy for so clean an image IMHO.', '2010-04-30 03:43:22.000000', NULL, 1),
(5980560, 873870, 37858, '<td valign="top">When I grow up I want to be able to make photos with this range of tones.  Very well done. 9</td>', 'When I grow up I want to be able to make photos with this range of tones.  Very well done. 9', '2010-04-30 03:44:37.000000', NULL, 1),
(5980561, 872977, 37858, '<td valign="top">Very nice.  I can imagine the colors in the sky even though everything is black and white.  8</td>', 'Very nice.  I can imagine the colors in the sky even though everything is black and white.  8', '2010-04-30 03:45:35.000000', NULL, 1),
(5980563, 872523, 37858, '<td valign="top">Very fine minimalist image.  Is that horizon angled or is that the way the far bank actually lies?</td>', 'Very fine minimalist image.  Is that horizon angled or is that the way the far bank actually lies?', '2010-04-30 03:47:39.000000', NULL, 1),
(5980565, 873987, 37858, '<td valign="top">Oh my.  This is just what I wanted my landscape photo to look like.  Too bad you have all the talent and I only have the idea.  (Of course, it didn''t help that I was shooting at 4 in the afternoon.)  Superb work. 10</td>', 'Oh my.  This is just what I wanted my landscape photo to look like.  Too bad you have all the talent and I only have the idea.  (Of course, it didn''t help that I was shooting at 4 in the afternoon.)  Superb work. 10', '2010-04-30 03:51:16.000000', NULL, 1),
(5980566, 874104, 37858, '<td valign="top">Really a fine range of tones in this photo.  8</td>', 'Really a fine range of tones in this photo.  8', '2010-04-30 03:52:58.000000', NULL, 1),
(5980567, 873469, 37858, '<td valign="top">Sweet.  10</td>', 'Sweet.  10', '2010-04-30 03:54:02.000000', NULL, 1),
(5980568, 874055, 37858, '<td valign="top">I haven''t figured out how to make my photos look like this.  I guess that''s why you get the 10 and I get the 5 or 6.  Nice work.</td>', 'I haven''t figured out how to make my photos look like this.  I guess that''s why you get the 10 and I get the 5 or 6.  Nice work.', '2010-04-30 03:56:36.000000', NULL, 1),
(5980570, 874127, 37858, '<td valign="top">Interesting effect.  I assume this was made after sundown on a moonlit night.  If not, I have no idea how you got what looks like stars and a shadow of the tree.</td>', 'Interesting effect.  I assume this was made after sundown on a moonlit night.  If not, I have no idea how you got what looks like stars and a shadow of the tree.', '2010-04-30 03:59:14.000000', NULL, 1),
(5980572, 873546, 37858, '<td valign="top">Nice tonal range and clarity for a setting that could easily end up as too busy.  Well done.</td>', 'Nice tonal range and clarity for a setting that could easily end up as too busy.  Well done.', '2010-04-30 04:00:14.000000', NULL, 1),
(5980574, 873727, 37858, '<td valign="top">You make a bunch of industrial waste look pretty inviting.  Well done.</td>', 'You make a bunch of industrial waste look pretty inviting.  Well done.', '2010-04-30 04:01:42.000000', NULL, 1),
(5980577, 872597, 37858, '<td valign="top">Very nice.</td>', 'Very nice.', '2010-04-30 04:03:11.000000', NULL, 1),
(5980585, 873767, 37858, '<td valign="top">This photo is very disorienting at first...then vertigo takes over.  Interesting landscape.</td>', 'This photo is very disorienting at first...then vertigo takes over.  Interesting landscape.', '2010-04-30 04:09:22.000000', NULL, 1),
(5980587, 873569, 37858, '<td valign="top">Great range of tones and a pleasing composition.  9</td>', 'Great range of tones and a pleasing composition.  9', '2010-04-30 04:12:12.000000', NULL, 1),
(5980588, 873647, 37858, '<td valign="top">The image has great tones but they are overrun by the heavy border.</td>', 'The image has great tones but they are overrun by the heavy border.', '2010-04-30 04:15:28.000000', NULL, 1),
(5980590, 874084, 37858, '<td valign="top">Nice photo but I could do without the heavy frame.</td>', 'Nice photo but I could do without the heavy frame.', '2010-04-30 04:18:21.000000', NULL, 1),
(5980592, 873674, 37858, '<td valign="top">Really a nice composition.</td>', 'Really a nice composition.', '2010-04-30 04:24:52.000000', NULL, 1),
(5980593, 873904, 37858, '<td valign="top">Very well done.</td>', 'Very well done.', '2010-04-30 04:25:35.000000', NULL, 1),
(5980649, 873674, 67152, '<td valign="top">lovely details and composition</td>', 'lovely details and composition', '2010-04-30 07:34:30.000000', NULL, 1),
(5980650, 873296, 67152, '<td valign="top">a bit too centered and not sharp enough</td>', 'a bit too centered and not sharp enough', '2010-04-30 07:34:56.000000', NULL, 1),
(5980651, 873736, 67152, '<td valign="top">i like how the creek seems to split open the sky - the polarizer seems to have created a ''too dark'' sky - 7</td>', 'i like how the creek seems to split open the sky - the polarizer seems to have created a ''too dark'' sky - 7', '2010-04-30 07:36:02.000000', NULL, 1),
(5980653, 872066, 67152, '<td valign="top">great details on the driftwood in the foreground - i personally would have closed down that aperture and let the whole scene be in focus</td>', 'great details on the driftwood in the foreground - i personally would have closed down that aperture and let the whole scene be in focus', '2010-04-30 07:37:27.000000', NULL, 1),
(5980654, 873574, 67152, '<td valign="top">i like the scene a lot - i just am not a fan of the overly strong contrast on the people</td>', 'i like the scene a lot - i just am not a fan of the overly strong contrast on the people', '2010-04-30 07:38:45.000000', NULL, 1),
(5980655, 874127, 67152, '<td valign="top">almost feels as if I am in a timewarp - cool stuff</td>', 'almost feels as if I am in a timewarp - cool stuff', '2010-04-30 07:39:30.000000', NULL, 1),
(5980656, 874062, 67152, '<td valign="top">lovely vista - the image seems a bit too bright</td>', 'lovely vista - the image seems a bit too bright', '2010-04-30 07:39:58.000000', NULL, 1),
(5980658, 872339, 67152, '<td valign="top">breathtaking location - i just wish there was a bit more foreground (something to ground the scene for the view)</td>', 'breathtaking location - i just wish there was a bit more foreground (something to ground the scene for the view)', '2010-04-30 07:41:10.000000', NULL, 1),
(5980659, 873820, 67152, '<td valign="top">a bit otherworldly with your choice of exposure/ processing</td>', 'a bit otherworldly with your choice of exposure/ processing', '2010-04-30 07:41:48.000000', NULL, 1),
(5980660, 874280, 67152, '<td valign="top">i love the low angle light on the foreground trees...</td>', 'i love the low angle light on the foreground trees...', '2010-04-30 07:42:07.000000', NULL, 1),
(5980661, 873345, 67152, '<td valign="top">love the quietness of this scene - i just think you could have toned down the sharpening a bit</td>', 'love the quietness of this scene - i just think you could have toned down the sharpening a bit', '2010-04-30 07:42:38.000000', NULL, 1),
(5980664, 872599, 67152, '<td valign="top">i love old RR bridges like this - and you did a nice job of capturing a bygone feel here...</td>', 'i love old RR bridges like this - and you did a nice job of capturing a bygone feel here...', '2010-04-30 07:44:02.000000', NULL, 1),
(5980665, 874223, 67152, '<td valign="top">the lighting of this lovely farm seems a bit too subdued, especially as it compares to the bright clouds</td>', 'the lighting of this lovely farm seems a bit too subdued, especially as it compares to the bright clouds', '2010-04-30 07:45:08.000000', NULL, 1),
(5980666, 874172, 67152, '<td valign="top">excellent use of high contrast here</td>', 'excellent use of high contrast here', '2010-04-30 07:45:24.000000', NULL, 1),
(5980668, 873862, 67152, '<td valign="top">lovely sky - cool use of repeating shapes to hold interest</td>', 'lovely sky - cool use of repeating shapes to hold interest', '2010-04-30 07:47:07.000000', NULL, 1),
(5980669, 873266, 67152, '<td valign="top">the layers of texture created by the water, boat, trees, hill and clouds really is well seen</td>', 'the layers of texture created by the water, boat, trees, hill and clouds really is well seen', '2010-04-30 07:47:57.000000', NULL, 1),
(5980670, 873712, 67152, '<td valign="top">gorgeous image - love the milky water</td>', 'gorgeous image - love the milky water', '2010-04-30 07:48:12.000000', NULL, 1),
(5980671, 871676, 67152, '<td valign="top">excellent details and perspective</td>', 'excellent details and perspective', '2010-04-30 07:48:45.000000', NULL, 1),
(5980673, 873013, 67152, '<td valign="top">i like the idea here - but the tree in the foreground makes my stop cold - i wonder leveraging the fence line more would have provided more appealing leading lines into/ across the scene.</td>', 'i like the idea here - but the tree in the foreground makes my stop cold - i wonder leveraging the fence line more would have provided more appealing leading lines into/ across the scene.', '2010-04-30 07:50:02.000000', NULL, 1),
(5980674, 872022, 67152, '<td valign="top">gorgeous</td>', 'gorgeous', '2010-04-30 07:50:20.000000', NULL, 1),
(5980675, 874229, 67152, '<td valign="top">a fairy tale scene</td>', 'a fairy tale scene', '2010-04-30 07:50:31.000000', NULL, 1),
