(5981273, 873242, 108069, '<td valign="top">Awesome. I also live in the vineyards but they''re still bare. great sky, and the barren tree just lends tot he starkness. Well done.</td>', 'Awesome. I also live in the vineyards but they''re still bare. great sky, and the barren tree just lends tot he starkness. Well done.', '2010-04-30 16:30:58.000000', NULL, 1),
(5981277, 873942, 57447, '<td valign="top">Nice view, I had haze in the distance in mine too.</td>', 'Nice view, I had haze in the distance in mine too.', '2010-04-30 16:34:52.000000', NULL, 1),
(5981278, 874207, 57447, '<td valign="top">Groovy</td>', 'Groovy', '2010-04-30 16:35:02.000000', NULL, 1),
(5981279, 873725, 57447, '<td valign="top">Goot title.  Love the tree in the center.</td>', 'Goot title.  Love the tree in the center.', '2010-04-30 16:36:08.000000', NULL, 1),
(5981291, 873994, 75713, '<td valign="top">Exposed well .. love the shapes, nice job of converting it to b&amp;w</td>', 'Exposed well .. love the shapes, nice job of converting it to b&w', '2010-04-30 16:42:59.000000', NULL, 1),
(5981294, 872401, 75713, '<td valign="top">Great title .. I like the sepia tones in this shot, adds to the drama of the title.</td>', 'Great title .. I like the sepia tones in this shot, adds to the drama of the title.', '2010-04-30 16:44:08.000000', NULL, 1),
(5981295, 874041, 75713, '<td valign="top">Very dramatic photo - great sky and you did a good job in converting it to b&amp;w.  The white on the church is almost glowing - interesting composition.</td>', 'Very dramatic photo - great sky and you did a good job in converting it to b&w.  The white on the church is almost glowing - interesting composition.', '2010-04-30 16:45:53.000000', NULL, 1),
(5981330, 872369, 75713, '<td valign="top">This image would look great even without the reflection but with the reflection you have taken this photo to a much higher level.  Great job of converting it to b&amp;w - great composition and kudos to you for entering such an interesting shot that really grabbed my eye.</td>', 'This image would look great even without the reflection but with the reflection you have taken this photo to a much higher level.  Great job of converting it to b&w - great composition and kudos to you for entering such an interesting shot that really grabbed my eye.', '2010-04-30 17:16:20.000000', NULL, 1),
(5981337, 874218, 75713, '<td valign="top">Living in California,  as I do, I see a lot of this type of devastation and the power fire has to wreak it. Your photo is a stark portrayal of what is left afterward - good job in the your pp.</td>', 'Living in California,  as I do, I see a lot of this type of devastation and the power fire has to wreak it. Your photo is a stark portrayal of what is left afterward - good job in the your pp.', '2010-04-30 17:21:26.000000', NULL, 1),
(5981338, 873596, 75713, '<td valign="top">Your title really fits your photo.  The dead branches of the tree does bring to mind the flow of a creek.  I like the drama in the sky - nice job pp.</td>', 'Your title really fits your photo.  The dead branches of the tree does bring to mind the flow of a creek.  I like the drama in the sky - nice job pp.', '2010-04-30 17:23:02.000000', NULL, 1),
(5981341, 873847, 75713, '<td valign="top">What an interesting shot.  I am making up all kinds of stories in my mind to suit it.  You did a good job making the ''slide'' stand out.  I wonder if there were more pure blacks or higher contrast if it would pop even more?</td>', 'What an interesting shot.  I am making up all kinds of stories in my mind to suit it.  You did a good job making the ''slide'' stand out.  I wonder if there were more pure blacks or higher contrast if it would pop even more?', '2010-04-30 17:28:10.000000', NULL, 1),
(5981343, 873251, 75713, '<td valign="top">Great job of isolating the white object given the limitations of basic editing.  The photo is stark and dramatic - nice job pp.</td>', 'Great job of isolating the white object given the limitations of basic editing.  The photo is stark and dramatic - nice job pp.', '2010-04-30 17:30:58.000000', NULL, 1),
(5981347, 872232, 75713, '<td valign="top">You''ve got a good tonal range in this photo - I like the contrast between the houses and the open fields - good title.</td>', 'You''ve got a good tonal range in this photo - I like the contrast between the houses and the open fields - good title.', '2010-04-30 17:33:36.000000', NULL, 1),
(5981364, 873736, 75713, '<td valign="top">I like the way the creek leads the eye into the photo. It reminds me of an infrared, which to me is a good thing.  Excellent focus and pp coupled with a great composition - I like the way the two lines of clouds in the sky echo the line of the creek.</td>', 'I like the way the creek leads the eye into the photo. It reminds me of an infrared, which to me is a good thing.  Excellent focus and pp coupled with a great composition - I like the way the two lines of clouds in the sky echo the line of the creek.', '2010-04-30 17:42:24.000000', NULL, 1),
(5981381, 873058, 75713, '<td valign="top">Great dramatic sky and I like how you made the footprints the main subject of the photo.  Nice job pp.</td>', 'Great dramatic sky and I like how you made the footprints the main subject of the photo.  Nice job pp.', '2010-04-30 17:53:34.000000', NULL, 1),
(5981385, 873654, 75713, '<td valign="top">Nice composition, interesting texture in the field and the grain in this shot really works.</td>', 'Nice composition, interesting texture in the field and the grain in this shot really works.', '2010-04-30 17:55:00.000000', NULL, 1),
(5981389, 874079, 75713, '<td valign="top">You did a great job of making the poppies pop - I love the tree .. it looks like a feather duster with it''s delicate foliage - great job in making the branches really stand out.  Lovely composition - this would make a great print.</td>', 'You did a great job of making the poppies pop - I love the tree .. it looks like a feather duster with it''s delicate foliage - great job in making the branches really stand out.  Lovely composition - this would make a great print.', '2010-04-30 17:58:18.000000', NULL, 1),
(5981392, 873546, 75713, '<td valign="top">exposed well .. this kind of shot with mottled light is difficult to capture and you did it well .. like the reflection in the stream.</td>', 'exposed well .. this kind of shot with mottled light is difficult to capture and you did it well .. like the reflection in the stream.', '2010-04-30 18:02:36.000000', NULL, 1),
(5981394, 872216, 75713, '<td valign="top">Your timing was dead on... great job exposing the sun.</td>', 'Your timing was dead on... great job exposing the sun.', '2010-04-30 18:03:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5981400, 872938, 75713, '<td valign="top">Amazing photo - your choice of making it a long exposure ensures this photo will place very high in this challenge along with the strong composition. You picked the right spot to photograph this image .. the bottom curve of the bridge nicely frames the rest of the image.</td>', 'Amazing photo - your choice of making it a long exposure ensures this photo will place very high in this challenge along with the strong composition. You picked the right spot to photograph this image .. the bottom curve of the bridge nicely frames the rest of the image.', '2010-04-30 18:08:48.000000', NULL, 1),
(5981406, 873231, 75713, '<td valign="top">Amazing cityscape - did you use a red filter by any chance?  Your focus is spot on and the composition is strong. Nice job!</td>', 'Amazing cityscape - did you use a red filter by any chance?  Your focus is spot on and the composition is strong. Nice job!', '2010-04-30 18:12:38.000000', NULL, 1),
(5981409, 873756, 75713, '<td valign="top">Interesting choice to shoot this in a portrait aspect.  I think you chose wisely.  The foreground is interesting and the beams of light in the sky makes this shot more dramatic.</td>', 'Interesting choice to shoot this in a portrait aspect.  I think you chose wisely.  The foreground is interesting and the beams of light in the sky makes this shot more dramatic.', '2010-04-30 18:18:44.000000', NULL, 1),
