(5983281, 873007, 30982, '<td valign="top">Love the study here - the old building, the newer ones behind, the peeps in the front, and of course - the pigeon!  Nice!</td>', 'Love the study here - the old building, the newer ones behind, the peeps in the front, and of course - the pigeon!  Nice!', '2010-05-01 19:16:25.000000', NULL, 1),
(5983282, 873605, 30982, '<td valign="top">Awesome view - great choice for the challenge.</td>', 'Awesome view - great choice for the challenge.', '2010-05-01 19:17:07.000000', NULL, 1),
(5983284, 873756, 30982, '<td valign="top">Love the foreground.  This works with the top chopped off, too, though perhaps not as a landscape and therefore not for this challenge...</td>', 'Love the foreground.  This works with the top chopped off, too, though perhaps not as a landscape and therefore not for this challenge...', '2010-05-01 19:17:44.000000', NULL, 1),
(5983286, 873814, 30982, '<td valign="top">Great light, wonderful use of the foreground and very good contrast.  Definitely printable!</td>', 'Great light, wonderful use of the foreground and very good contrast.  Definitely printable!', '2010-05-01 19:18:38.000000', NULL, 1),
(5983287, 874293, 30982, '<td valign="top">Lovely gentleness to this.</td>', 'Lovely gentleness to this.', '2010-05-01 19:18:52.000000', NULL, 1),
(5983289, 873656, 30982, '<td valign="top">Lovely shades of light gray.</td>', 'Lovely shades of light gray.', '2010-05-01 19:19:47.000000', NULL, 1),
(5983291, 872348, 30982, '<td valign="top">Quite serene and lovely tonal range in this.</td>', 'Quite serene and lovely tonal range in this.', '2010-05-01 19:20:02.000000', NULL, 1),
(5983293, 873566, 30982, '<td valign="top">My kind of landscape - well seen, well captured.  I like the blown out bits eating into the top of the hill/dune.</td>', 'My kind of landscape - well seen, well captured.  I like the blown out bits eating into the top of the hill/dune.', '2010-05-01 19:20:56.000000', NULL, 1),
(5983294, 874261, 30982, '<td valign="top">Lovely processing - excellent tones in this.</td>', 'Lovely processing - excellent tones in this.', '2010-05-01 19:21:29.000000', NULL, 1),
(5983295, 871850, 30982, '<td valign="top">The do make a lovely foreground flower!  Nice use of portrait orientation as well.</td>', 'The do make a lovely foreground flower!  Nice use of portrait orientation as well.', '2010-05-01 19:21:54.000000', NULL, 1),
(5983298, 874167, 30982, '<td valign="top">I just plain like this.</td>', 'I just plain like this.', '2010-05-01 19:22:29.000000', NULL, 1),
(5983300, 873332, 30982, '<td valign="top">Very nice processing, lovely perspective to show off the tree and incorporate the landscape as well.</td>', 'Very nice processing, lovely perspective to show off the tree and incorporate the landscape as well.', '2010-05-01 19:22:50.000000', NULL, 1),
(5983303, 873531, 30982, '<td valign="top">I really do think this is one of the strongest entries from our team.  And I bet this would look lovely printed!</td>', 'I really do think this is one of the strongest entries from our team.  And I bet this would look lovely printed!', '2010-05-01 19:25:53.000000', NULL, 1),
(5983304, 872540, 91360, '<td valign="top">i would have turn this 90deg ccw..</td>', 'i would have turn this 90deg ccw..', '2010-05-01 19:27:37.000000', NULL, 1),
(5983321, 874102, 91360, '<td valign="top">front angel.. wide open could have done much better here..</td>', 'front angel.. wide open could have done much better here..', '2010-05-01 19:45:14.000000', NULL, 1),
(5983323, 873358, 92847, '<td valign="top">Very well done! Fantastic shot, love it.</td>', 'Very well done! Fantastic shot, love it.', '2010-05-01 19:45:53.000000', NULL, 1),
(5983324, 871856, 92847, '<td valign="top">WOW! Amazing shot. Winner!</td>', 'WOW! Amazing shot. Winner!', '2010-05-01 19:45:59.000000', NULL, 1),
(5983326, 872548, 92847, '<td valign="top">Outstanding image, excellent!</td>', 'Outstanding image, excellent!', '2010-05-01 19:46:44.000000', NULL, 1),
(5983329, 872938, 92847, '<td valign="top">Very nice angle, well done.</td>', 'Very nice angle, well done.', '2010-05-01 19:48:05.000000', NULL, 1),
(5983344, 872548, 36616, '<td valign="top">Crystal clear. Well done</td>', 'Crystal clear. Well done', '2010-05-01 19:56:31.000000', NULL, 1),
(5983346, 873605, 36616, '<td valign="top">Fabulous location and well executed pic. Well done</td>', 'Fabulous location and well executed pic. Well done', '2010-05-01 19:56:42.000000', NULL, 1),
(5983348, 874124, 36616, '<td valign="top">Yet another great pic of Sydney. Well done</td>', 'Yet another great pic of Sydney. Well done', '2010-05-01 19:56:48.000000', NULL, 1),
(5983349, 873569, 36616, '<td valign="top">Glorious shot. Well done</td>', 'Glorious shot. Well done', '2010-05-01 19:56:53.000000', NULL, 1),
(5983350, 873773, 36616, '<td valign="top">Plenty to look at and hold my attention - well done</td>', 'Plenty to look at and hold my attention - well done', '2010-05-01 19:56:59.000000', NULL, 1),
(5983354, 872179, 36616, '<td valign="top">Gorgeous scene - so peaceful. Well done</td>', 'Gorgeous scene - so peaceful. Well done', '2010-05-01 19:58:01.000000', NULL, 1),
(5983355, 873994, 36616, '<td valign="top">Great shot - how positive an altitude exactly?</td>', 'Great shot - how positive an altitude exactly?', '2010-05-01 19:58:29.000000', NULL, 1),
(5983357, 872011, 36616, '<td valign="top">Good location and execution. Like it very much</td>', 'Good location and execution. Like it very much', '2010-05-01 19:58:58.000000', NULL, 1),
(5983358, 873231, 36616, '<td valign="top">Tremendous detail. Will come back later to get more details - congratulations on a first class shot</td>', 'Tremendous detail. Will come back later to get more details - congratulations on a first class shot', '2010-05-01 19:59:03.000000', NULL, 1),
(5983359, 873292, 36616, '<td valign="top">Love the symmetry here</td>', 'Love the symmetry here', '2010-05-01 19:59:07.000000', NULL, 1),
(5983379, 873393, 36616, '<td valign="top">Could have worked well in portrait orientation - understand why you wouldn''t use it here.</td>', 'Could have worked well in portrait orientation - understand why you wouldn''t use it here.', '2010-05-01 20:09:40.000000', NULL, 1),
(5983380, 873144, 36616, '<td valign="top">Very good. Sydney seems to have produced some stunning shots this week</td>', 'Very good. Sydney seems to have produced some stunning shots this week', '2010-05-01 20:09:44.000000', NULL, 1),
(5983384, 874101, 36616, '<td valign="top">Like it.</td>', 'Like it.', '2010-05-01 20:12:34.000000', NULL, 1),
(5983385, 873033, 36616, '<td valign="top">This works well in this orientation. Would think you may have suffered by being honest to your shot</td>', 'This works well in this orientation. Would think you may have suffered by being honest to your shot', '2010-05-01 20:12:37.000000', NULL, 1),
(5983393, 872437, 36616, '<td valign="top">Great scene - overall effect is rather dark.</td>', 'Great scene - overall effect is rather dark.', '2010-05-01 20:16:57.000000', NULL, 1),
(5983394, 873671, 36616, '<td valign="top">The plane adds a lot to this pic</td>', 'The plane adds a lot to this pic', '2010-05-01 20:17:20.000000', NULL, 1),
(5983397, 874184, 36616, '<td valign="top">Super reflections. Good shot - location simply beaten by some others.</td>', 'Super reflections. Good shot - location simply beaten by some others.', '2010-05-01 20:20:10.000000', NULL, 1),
(5983411, 872146, 90626, '<td valign="top">very nice. was there 15 years ago.</td>', 'very nice. was there 15 years ago.', '2010-05-01 20:36:18.000000', NULL, 1),
(5983415, 872244, 90626, '<td valign="top">wires are distracting for me. would do with a little more crop on the left. very nice scenery.</td>', 'wires are distracting for me. would do with a little more crop on the left. very nice scenery.', '2010-05-01 20:38:11.000000', NULL, 1),
(5983417, 874050, 90626, '<td valign="top">little busy for me. my eyes are searching for a landing.</td>', 'little busy for me. my eyes are searching for a landing.', '2010-05-01 20:39:28.000000', NULL, 1),
(5983419, 873344, 90626, '<td valign="top">i like the reflections.</td>', 'i like the reflections.', '2010-05-01 20:40:06.000000', NULL, 1),
(5983420, 873676, 90626, '<td valign="top">excellent shadows</td>', 'excellent shadows', '2010-05-01 20:40:45.000000', NULL, 1),
(5983421, 874223, 90626, '<td valign="top">good contrasts. maybe crop some sky from top so farmland looks a little larger in overall.</td>', 'good contrasts. maybe crop some sky from top so farmland looks a little larger in overall.', '2010-05-01 20:43:20.000000', NULL, 1),
(5983459, 873739, 90626, '<td valign="top">a little cropping of the top sky would enhance the castle a bit. nice choice.</td>', 'a little cropping of the top sky would enhance the castle a bit. nice choice.', '2010-05-01 21:29:33.000000', NULL, 1),
(5983471, 874184, 64086, '<td valign="top">I like how the bridge frames the pillars in the background. Nice photo!</td>', 'I like how the bridge frames the pillars in the background. Nice photo!', '2010-05-01 21:38:35.000000', NULL, 1),
(5983477, 874199, 64086, '<td valign="top">I think cropping off some of the bottom improves the composition. I love the light that''s on, in the top window of the tower.</td>', 'I think cropping off some of the bottom improves the composition. I love the light that''s on, in the top window of the tower.', '2010-05-01 21:43:03.000000', NULL, 1),
(5983478, 873021, 82749, '<td valign="top">Love those covered bridges!  (No vote, just a comment)</td>', 'Love those covered bridges!  (No vote, just a comment)', '2010-05-01 21:43:14.000000', NULL, 1),
(5983481, 873239, 82749, '<td valign="top">Great scene, but seems a bit on the dark side for my taste.  (No vote, just a comment)</td>', 'Great scene, but seems a bit on the dark side for my taste.  (No vote, just a comment)', '2010-05-01 21:44:17.000000', NULL, 1),
(5983484, 874027, 82749, '<td valign="top">Nice patterns made by the multi-level waterfall.    (No vote, just a comment)</td>', 'Nice patterns made by the multi-level waterfall.    (No vote, just a comment)', '2010-05-01 21:45:43.000000', NULL, 1),
(5983497, 873144, 82749, '<td valign="top">Nice image, almost 2-for-1.  Regarding title, clouds look stormy enough, but water seems relatively smooth.  (No vote, just a comment)</td>', 'Nice image, almost 2-for-1.  Regarding title, clouds look stormy enough, but water seems relatively smooth.  (No vote, just a comment)', '2010-05-01 21:52:43.000000', NULL, 1),
(5983498, 873698, 82749, '<td valign="top">Nice mountainous scene.  I have mixed feelings about person being there.  (No vote, just a comment)</td>', 'Nice mountainous scene.  I have mixed feelings about person being there.  (No vote, just a comment)', '2010-05-01 21:54:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5983501, 873822, 82749, '<td valign="top">(No vote, just a comment)  Nice image, I like the repeating patterns.  (Hopefully the voters aren''t punishing you for submitting something that is smaller than 800 pixels wide.)</td>', '(No vote, just a comment)  Nice image, I like the repeating patterns.  (Hopefully the voters aren''t punishing you for submitting something that is smaller than 800 pixels wide.)', '2010-05-01 21:56:38.000000', NULL, 1),
(5983502, 872599, 82749, '<td valign="top">Nice reflection  (No vote, just a comment)</td>', 'Nice reflection  (No vote, just a comment)', '2010-05-01 21:57:17.000000', NULL, 1),
(5983577, 873736, 103142, '<td valign="top">I love the sky, but I think the composition of splitting the photo basically in half both halves less important. It might be stronger if you placed the horizon at the top 1/3. You''d still retain much of the interesting sky, but it would also give more importance to the creek.</td>', 'I love the sky, but I think the composition of splitting the photo basically in half both halves less important. It might be stronger if you placed the horizon at the top 1/3. You''d still retain much of the interesting sky, but it would also give more importance to the creek.', '2010-05-01 23:00:32.000000', NULL, 1),
(5983586, 872802, 103142, '<td valign="top">The church is marvelous and the reflection is great. Unfortunately, the item on the right (I''m sorry, I can''t even tell what it is) is distracting; I don''t think it adds to the picture, only detracts. I''d be interested in seeing what it looks like cropped in a little from the left and cropped in significantly from the right. 5 as is, but I think it could have been as much as a 7 with a different crop.</td>', 'The church is marvelous and the reflection is great. Unfortunately, the item on the right (I''m sorry, I can''t even tell what it is) is distracting; I don''t think it adds to the picture, only detracts. I''d be interested in seeing what it looks like cropped in a little from the left and cropped in significantly from the right. 5 as is, but I think it could have been as much as a 7 with a different crop.', '2010-05-01 23:05:17.000000', NULL, 1),
(5983588, 872877, 103142, '<td valign="top">Wonderful! I love the negative space on the right. I wish we could have larger sizes for landscape orientation. I bet this would be much more spectacular at around 1400 pixels!</td>', 'Wonderful! I love the negative space on the right. I wish we could have larger sizes for landscape orientation. I bet this would be much more spectacular at around 1400 pixels!', '2010-05-01 23:06:17.000000', NULL, 1),
(5983660, 873294, 76335, '<td valign="top">(29/38) Nice, if a little dark and maybe lacking contrast. I do like the composition.</td>', '(29/38) Nice, if a little dark and maybe lacking contrast. I do like the composition.', '2010-05-02 00:20:34.000000', NULL, 1),
(5983662, 874295, 76335, '<td valign="top">(30/38) I feel drawn right into it. This is beautiful.</td>', '(30/38) I feel drawn right into it. This is beautiful.', '2010-05-02 00:21:04.000000', NULL, 1),
(5983664, 872653, 76335, '<td valign="top">(31/38) Your pond looks like a lake! Beautiful reflection, and I like the framing on three sides by the grass and trees.</td>', '(31/38) Your pond looks like a lake! Beautiful reflection, and I like the framing on three sides by the grass and trees.', '2010-05-02 00:23:16.000000', NULL, 1),
(5983671, 873658, 76335, '<td valign="top">(32/38) The clouds complement your subject nicely. Feels like something out of a fairy tale.</td>', '(32/38) The clouds complement your subject nicely. Feels like something out of a fairy tale.', '2010-05-02 00:29:03.000000', NULL, 1),
(5983672, 873573, 76335, '<td valign="top">(33/38) Interesting, but, since we''re seeing everything in silhouette, I think a singular, dominant structure to anchor the scene would have helped.</td>', '(33/38) Interesting, but, since we''re seeing everything in silhouette, I think a singular, dominant structure to anchor the scene would have helped.', '2010-05-02 00:30:05.000000', NULL, 1),
(5983673, 873991, 76335, '<td valign="top">(34/38) I like the subtle gradient in the hills/mountains, and the foreground brush anchors the scene quite nicely.</td>', '(34/38) I like the subtle gradient in the hills/mountains, and the foreground brush anchors the scene quite nicely.', '2010-05-02 00:30:50.000000', NULL, 1),
(5983675, 873865, 75713, '<td valign="top">What an amazing view you had ... nice example of the rule of thirds - the sky lacks detail, maybe due to the fog rolling in.  Nice job on revealing the texture of the trees. All in all, a good job, especially when you only had basic editing to work with.</td>', 'What an amazing view you had ... nice example of the rule of thirds - the sky lacks detail, maybe due to the fog rolling in.  Nice job on revealing the texture of the trees. All in all, a good job, especially when you only had basic editing to work with.', '2010-05-02 00:31:48.000000', NULL, 1),
(5983676, 874298, 75713, '<td valign="top">Delicate is the word that comes to mind when I look at this beautiful photo.  It looks like a magical place, due in no small part to your great job in pp.</td>', 'Delicate is the word that comes to mind when I look at this beautiful photo.  It looks like a magical place, due in no small part to your great job in pp.', '2010-05-02 00:33:16.000000', NULL, 1),
(5983680, 873862, 76335, '<td valign="top">(35/38) Black and white works especially well here to show off the rhythm inherent in this field of young trees.</td>', '(35/38) Black and white works especially well here to show off the rhythm inherent in this field of young trees.', '2010-05-02 00:35:01.000000', NULL, 1),
(5983682, 874194, 76335, '<td valign="top">(36/38) This is nicely composed. Looks like a telephoto shot, which I like because it tends to flatten the whole scene and emphasize the shapes in the skyline.</td>', '(36/38) This is nicely composed. Looks like a telephoto shot, which I like because it tends to flatten the whole scene and emphasize the shapes in the skyline.', '2010-05-02 00:36:12.000000', NULL, 1),
(5983684, 873709, 75713, '<td valign="top">This photo looks like a silver print and is just beautiful.  The sky is dramatic and it lit the hill perfectly.  Your composition is wonderful - the trees are placed in such a way as to help guide the eye to the monument and the sky .. nothing to suggest in the way of improving on this photo.</td>', 'This photo looks like a silver print and is just beautiful.  The sky is dramatic and it lit the hill perfectly.  Your composition is wonderful - the trees are placed in such a way as to help guide the eye to the monument and the sky .. nothing to suggest in the way of improving on this photo.', '2010-05-02 00:36:55.000000', NULL, 1),
(5983688, 874172, 76335, '<td valign="top">(37/38) Simple and beautifully done. I like the textures and subtle details (like the background fence).</td>', '(37/38) Simple and beautifully done. I like the textures and subtle details (like the background fence).', '2010-05-02 00:37:48.000000', NULL, 1),
(5983689, 873239, 75713, '<td valign="top">Wonderful tonal quality and the flight of the birds add even more motion to this excellent shot.</td>', 'Wonderful tonal quality and the flight of the birds add even more motion to this excellent shot.', '2010-05-02 00:37:49.000000', NULL, 1),
(5983691, 874027, 76335, '<td valign="top">(38/38) We''ve all seen this before (or a scene just like it), but that doesn''t take away from the beauty of it or the expertise with which you''ve captured it. Nicely done.</td>', '(38/38) We''ve all seen this before (or a scene just like it), but that doesn''t take away from the beauty of it or the expertise with which you''ve captured it. Nicely done.', '2010-05-02 00:39:11.000000', NULL, 1),
(5983699, 872088, 75713, '<td valign="top">Nice job in converting this shot to b&amp;w.  The sky adds drama to this photo, which would otherwise not hold my attention. I like the soft edge of the grass because it frames the shot,given that the top of the frame shows a sky that is almost the same tone.</td>', 'Nice job in converting this shot to b&w.  The sky adds drama to this photo, which would otherwise not hold my attention. I like the soft edge of the grass because it frames the shot,given that the top of the frame shows a sky that is almost the same tone.', '2010-05-02 00:43:10.000000', NULL, 1),
(5983701, 873030, 76335, '<td valign="top">Original! Has both geographical and geometrical intrigue.</td>', 'Original! Has both geographical and geometrical intrigue.', '2010-05-02 00:45:14.000000', NULL, 1),
(5983706, 873938, 75713, '<td valign="top">What a refreshing take on moving water - I love the abstract quality of this shot. Great job in converting it to b&amp;w - a magical looking photo.</td>', 'What a refreshing take on moving water - I love the abstract quality of this shot. Great job in converting it to b&w - a magical looking photo.', '2010-05-02 00:47:12.000000', NULL, 1),
(5983707, 874218, 76335, '<td valign="top">Great idea, beautifully done. It does feel of death and devastation, but also of rebirth and new beginnings. So goes nature...</td>', 'Great idea, beautifully done. It does feel of death and devastation, but also of rebirth and new beginnings. So goes nature...', '2010-05-02 00:47:21.000000', NULL, 1),
(5983709, 874082, 76335, '<td valign="top">Too cool to vote down. I''ll buy it.</td>', 'Too cool to vote down. I''ll buy it.', '2010-05-02 00:48:00.000000', NULL, 1),
(5983710, 874217, 76335, '<td valign="top">Wasn''t sure initially what the tilt was adding, but it does emphasize the radial geometry and the converging lines. Cool.</td>', 'Wasn''t sure initially what the tilt was adding, but it does emphasize the radial geometry and the converging lines. Cool.', '2010-05-02 00:48:43.000000', NULL, 1),
(5983711, 873020, 76335, '<td valign="top">I imagine you''re getting lots of comments about how blurry this is. Don''t know if it was intentional, and I''d be hard pressed to say why, but I think it works.</td>', 'I imagine you''re getting lots of comments about how blurry this is. Don''t know if it was intentional, and I''d be hard pressed to say why, but I think it works.', '2010-05-02 00:50:08.000000', NULL, 1),
(5983712, 873628, 76335, '<td valign="top">Fabulous title for a fabulous image.</td>', 'Fabulous title for a fabulous image.', '2010-05-02 00:50:53.000000', NULL, 1),
(5983713, 874233, 75713, '<td valign="top">Nice having access to falls like these. A long exposure was certainly the way to go.  For me, I would have made it b&amp;w, but that is a personal taste as I find sepia takes away the impact of the water.  Great composition and nice job exposing the details in the trees.</td>', 'Nice having access to falls like these. A long exposure was certainly the way to go.  For me, I would have made it b&w, but that is a personal taste as I find sepia takes away the impact of the water.  Great composition and nice job exposing the details in the trees.', '2010-05-02 00:50:58.000000', NULL, 1),
(5983715, 871850, 76335, '<td valign="top">Good job not losing those ubiquitous but delicate little flowers in the black and white conversion. They really stand out here.</td>', 'Good job not losing those ubiquitous but delicate little flowers in the black and white conversion. They really stand out here.', '2010-05-02 00:52:25.000000', NULL, 1),
(5983716, 874289, 75713, '<td valign="top">A very well done photo .. the exposure is amazing .. did you shoot it after sunset?</td>', 'A very well done photo .. the exposure is amazing .. did you shoot it after sunset?', '2010-05-02 00:53:08.000000', NULL, 1),
(5983722, 873861, 103410, '<td valign="top">This image could be adjusted using HDR technique. There are very dark areas that make a hard contrast with the light areas.</td>', 'This image could be adjusted using HDR technique. There are very dark areas that make a hard contrast with the light areas.', '2010-05-02 00:58:11.000000', NULL, 1),
(5983729, 873263, 103410, '<td valign="top">This image could be cropped a little in the top side..too much clouds distract from the main subject</td>', 'This image could be cropped a little in the top side..too much clouds distract from the main subject', '2010-05-02 01:00:20.000000', NULL, 1),
(5983731, 874124, 103410, '<td valign="top">Nice bulb picture..</td>', 'Nice bulb picture..', '2010-05-02 01:01:21.000000', NULL, 1),
(5983803, 873596, 106910, '<td valign="top">The tree doesn''t stand out enough against the grassy foreground - it''s almost camouflaged.</td>', 'The tree doesn''t stand out enough against the grassy foreground - it''s almost camouflaged.', '2010-05-02 02:37:37.000000', NULL, 1),
(5983804, 873554, 106910, '<td valign="top">It feels tilted to the right - which may have to do with the tree line and the sky only being in the top right side of the photo. Either way - I feel unbalanced.</td>', 'It feels tilted to the right - which may have to do with the tree line and the sky only being in the top right side of the photo. Either way - I feel unbalanced.', '2010-05-02 02:38:29.000000', NULL, 1),
(5983805, 873332, 106910, '<td valign="top">I really like this - it almost has an ethereal quality to it. Nicely done.</td>', 'I really like this - it almost has an ethereal quality to it. Nicely done.', '2010-05-02 02:39:56.000000', NULL, 1),
(5983807, 872309, 106910, '<td valign="top">Very nice contrast - and great time of shot.</td>', 'Very nice contrast - and great time of shot.', '2010-05-02 02:40:36.000000', NULL, 1),
(5983808, 872369, 106910, '<td valign="top">I really like the mirrored effect in this photo</td>', 'I really like the mirrored effect in this photo', '2010-05-02 02:40:52.000000', NULL, 1),
(5983810, 873386, 106910, '<td valign="top">Infrared, right? I like it.</td>', 'Infrared, right? I like it.', '2010-05-02 02:41:53.000000', NULL, 1),
(5983811, 872511, 106910, '<td valign="top">Honestly - the plant in dead-center distracts from the photo as a whole and the title.</td>', 'Honestly - the plant in dead-center distracts from the photo as a whole and the title.', '2010-05-02 02:41:56.000000', NULL, 1),
(5983825, 872877, 23430, '<td valign="top">Spectacular</td>', 'Spectacular', '2010-05-02 03:22:03.000000', NULL, 1),
(5983830, 872656, 23430, '<td valign="top">Very tidy.</td>', 'Very tidy.', '2010-05-02 03:24:27.000000', NULL, 1),
(5983834, 872146, 23430, '<td valign="top">Love the Clouds. Overall scene is nice. Not sure keen on the Rocks in the foreground.</td>', 'Love the Clouds. Overall scene is nice. Not sure keen on the Rocks in the foreground.', '2010-05-02 03:27:19.000000', NULL, 1),
(5983840, 872315, 23430, '<td valign="top">Like the water your photo has a nice flow to it.</td>', 'Like the water your photo has a nice flow to it.', '2010-05-02 03:34:06.000000', NULL, 1),
