(5984271, 873625, 76335, '<td valign="top">Beautifully composed. The trees and lake set off the background cityscape quite effectively.</td>', 'Beautifully composed. The trees and lake set off the background cityscape quite effectively.', '2010-05-02 11:07:53.000000', NULL, 1),
