INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5986204, 873251, 42013, '<td valign="top">Of all the entries in this challenge, this one stood out! Good work.</td>', 'Of all the entries in this challenge, this one stood out! Good work.', '2010-05-03 01:54:28.000000', NULL, 0),
(5986207, 873231, 52713, '<td valign="top">Nice finish! Knew this was yours!</td>', 'Nice finish! Knew this was yours!', '2010-05-03 01:55:51.000000', NULL, 0),
(5986213, 874246, 68504, '<td valign="top">You''ve used the light to make a very sensuous texture, almost like cake frosting but not too sweet. I like the Mondrian lines (more than I like Mondrian).  The shadow on the window is stunning.</td>', 'You''ve used the light to make a very sensuous texture, almost like cake frosting but not too sweet. I like the Mondrian lines (more than I like Mondrian).  The shadow on the window is stunning.', '2010-05-03 01:56:34.000000', NULL, 0),
(5986218, 872548, 55956, '<td valign="top">Congratulations!!!!!!!!!!!!!!!!!!!!!!!!!!!</td>', 'Congratulations!!!!!!!!!!!!!!!!!!!!!!!!!!!', '2010-05-03 01:57:32.000000', NULL, 0),
